window.TOPIC_ORDER=["Javaプログラムの基本", "データ型と変数", "型変換", "演算子", "制御構文", "文字列", "配列とリスト", "クラスとメソッド", "コンストラクタと初期化", "継承とポリモーフィズム", "抽象クラスとインターフェース", "sealed・record・enum", "例外処理", "ラムダとAPI", "パッケージとモジュール", "総合問題"];
window.QUESTIONS=[{"id":"conv-001","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"long l = 10L;\nfloat f = l;\nSystem.out.println(f);","choices":["10","10.0","10L","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[1],"explain":"long → float は拡大方向なので自動で変換される（long は64ビット、float は32ビットだが、表せる範囲は float の方が広い）。f は float 型なので 10.0 と表示される。表示は「今入っている変数の型」で決まる。","topic":"型変換","mono":1},{"id":"conv-002","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"char c = 'a';\nint i = c;\nSystem.out.println(i);","choices":["a","97","'a'","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[1],"explain":"char → int はキャスト不要（char は16ビットで int に収まる）。i は int 型なので、文字コードの 97 が数値として表示される。char から自動で広がるのは int・long・float・double だけで、byte・short へはキャストが要る。逆に、ほかの数値型から char へはどの型からでもキャストが要る（範囲内の定数を除く）。","topic":"型変換","mono":1},{"id":"conv-003","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int i = 300;\nbyte b = (byte) i;\nSystem.out.println(b);","choices":["300","127","44","-56","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[2],"explain":"byte は8ビット（-128〜127）。int の下位8ビットだけが残る。300 = 256 + 44 なので 44。","topic":"型変換","mono":1},{"id":"conv-004","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"double d = -1.99;\nSystem.out.println((int) d);","choices":["-1","-2","1","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"浮動小数点数から整数へのキャストは四捨五入ではなく切り捨て（0の方向）。-1.99 → -1。","topic":"型変換","mono":1},{"id":"conv-005","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"double d = 3.99;\nint i = d;\nSystem.out.println(i);","choices":["3","4","3.99","2行目でコンパイルエラー"],"answer":[3],"explain":"double → int は縮小方向なので自動では変換されない（possible lossy conversion from double to int）。int i = (int) d; と書けば 3。","topic":"型変換"},{"id":"conv-006","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"byte b = 65;\nchar c = (char) b;\nSystem.out.println(c);","choices":["65","A","a","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[1],"explain":"c は char 型なので、65 は文字コードとして読まれ A と表示される。変数どうしなら byte → char はキャスト必須（キャストが無いとコンパイルエラー）。","topic":"型変換","mono":1},{"id":"conv-007","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["short s = 5; long l = s;","long l = 5L; int i = l;","char c = 'A'; short s = c;","int i = 5; float f = i;","byte b = 10; char c = b;"],"answer":[1,2,4],"explain":"縮小方向（long→int）はキャスト必須。変数どうしなら、char と byte・short の間はどちら向きもキャスト必須（char は符号なし16ビット、short は符号あり16ビットで範囲がずれるため）。short→long、int→float は拡大なので自動。","topic":"型変換","mono":1},{"id":"conv-008","type":"single","q":"次のうち、暗黙の型変換（拡大）の順序として正しいものは？","choices":["byte → short → int → long → float → double","double → float → long → int → short → byte","byte → short → int → float → long → double","int → byte → short → long → float → double"],"answer":[0],"explain":"小さい型から大きい型へは自動（拡大変換）。逆向き（縮小変換）は原則キャスト (型) が必要（例外：範囲内の定数の代入、+= などの複合代入）。double が一番大きい。char はこの列の外で、int 以上へは自動で広がるが、byte・short との間はどちら向きもキャストが要る。","topic":"型変換"},{"id":"conv-009","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"final int n = 10;\nbyte b = n;\nSystem.out.println(b);","choices":["10","コンパイルエラー","実行時に例外","0"],"answer":[0],"explain":"宣言と同時に定数（リテラルなど）で初期化した final の int 変数は定数として扱われ、値が byte の範囲（-128〜127）に収まればキャスト無しで byte に代入できる。final が無い int 変数や、後から代入する final 変数（final int n; n = 10;）だと possible lossy conversion でエラーになる。","topic":"型変換","mono":1},{"id":"conv-010","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"byte b = 10;\nb = b + 1;\nSystem.out.println(b);","choices":["11","10","2行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"byte 同士・byte と int の算術演算の結果は int になる。int を byte に入れるにはキャストが必要。なお b += 1; なら複合代入演算子が暗黙にキャストするので通る（11）。","topic":"型変換"},{"id":"conv-011","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"byte b = 10;\nb += 1;\nSystem.out.println(b);","choices":["11","コンパイルエラー","10","実行時に例外"],"answer":[0],"explain":"+= などの複合代入演算子は、結果を左辺の型へ暗黙にキャストする。b = b + 1; はエラーだが b += 1; は通る。","topic":"型変換","mono":1},{"id":"basic-001","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int a = 0b1010;\nint b = 010;\nint c = 0x1F;\nSystem.out.println(a + b + c);","choices":["49","1041","1010831","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"0b（または0B）で始まると2進数、0で始まると8進数、0x（または0X）で始まると16進数のリテラルになる。0b1010は10、010は8（10ではない）、0x1Fは31なので、合計は49。println に渡した時点では全部ただの int の値で、何進数で書いたかは残らない。","topic":"データ型と変数","mono":1,"sub":"データ型"},{"id":"basic-002","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["int a = 1_000_000;","int b = 100_;","double d = 3_.14;","int f = 0_7;","long e = 0x_FFL;"],"answer":[1,2,4],"explain":"数値リテラルのアンダースコアは「数字と数字の間」にだけ置ける。末尾（100_）、小数点の隣（3_.14）、接頭辞 0x の直後（0x_FF）、接尾辞 L・F の直前は不可。0_7 は先頭の 0 も数字扱いなので間に入っていることになり、8進数の 7 として通る。","topic":"データ型と変数","mono":1,"sub":"データ型"},{"id":"basic-003","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"char c = 'A';\nc += 2;\nSystem.out.println(c + \" \" + ('A' + 2));","choices":["C 67","C C","67 67","C A2","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"c += 2 は複合代入なので結果が char に戻され、c は 'C' になる。一方 'A' + 2 は char と int の算術演算なので結果は int の 67。表示は「その式の型」で決まり、char なら文字、int なら数値になる。","topic":"データ型と変数","mono":1,"sub":"データ型"},{"id":"basic-004","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["var a = 10;","var b;\nb = 10;","var c = null;","var d = {1, 2};","var e = new int[]{1, 2};"],"answer":[1,2,3],"explain":"var は初期化式から型を推論するので、宣言と同時に初期化が必須。null や配列初期化子 {1, 2} だけでは型が決まらないのでエラー。new int[]{1, 2} のように型が書いてあれば推論できる。","topic":"データ型と変数","mono":1,"sub":"var"},{"id":"basic-005","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    var count = 0;\n    public static void main(String[] args) {\n        var x = 5;\n        System.out.println(x);\n    }\n}","choices":["5","0","2行目でコンパイルエラー","4行目でコンパイルエラー"],"answer":[2],"explain":"var を使えるのはローカル変数（メソッド・コンストラクタ・初期化ブロックの中の変数、for 文・拡張 for の変数、try-with-resources のリソース）と、ラムダ式の引数だけ。フィールド、メソッドやコンストラクタの引数、戻り値の型、catch の引数には使えない。ここでは2行目のフィールド宣言がエラーになる。","topic":"データ型と変数","sub":"var"},{"id":"basic-006","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"var n = 10;\nn = n / 4.0;\nSystem.out.println(n);","choices":["2.5","2","2行目でコンパイルエラー","1行目でコンパイルエラー"],"answer":[2],"explain":"var n = 10; で n の型は int に確定し、あとから変わることはない（動的型付けではない）。n / 4.0 は double なので、int の n に代入しようとして possible lossy conversion のエラーになる。","topic":"データ型と変数","sub":"var"},{"id":"basic-007","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int x = 2 + 3 * 4 % 5 - 1;\nSystem.out.println(x);","choices":["3","-1","19","8","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"* / % は + - より優先順位が高く、同じ優先順位どうしは左から順に計算する。3 * 4 = 12、12 % 5 = 2 が先に決まり、2 + 2 - 1 = 3。左から素直に計算すると -1 になる罠。","topic":"演算子","mono":1},{"id":"basic-008","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int i = 5;\nint j = i++ + ++i;\nSystem.out.println(i + \" \" + j);","choices":["7 12","7 11","6 11","7 13","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"後置 i++ は「今の値を式に使ってから」1増やし、前置 ++i は「1増やしてから」その値を使う。i++ は 5 を返して i が 6 になり、続く ++i で i が 7 になって 7 を返す。j = 5 + 7 = 12。","topic":"演算子","mono":1},{"id":"basic-009","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int i = 3;\ni = i++;\nSystem.out.println(i);","choices":["3","4","5","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"i = i++; は、右辺の i++ がまず元の値 3 を返し、そのあと i が 4 になるが、最後に代入で右辺の値 3 が i に書き戻される。結果として i は 3 のまま。","topic":"演算子","mono":1},{"id":"basic-010","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int x = 1;\nboolean b = (x > 5) && (++x > 1);\nboolean c = (x > 5) & (++x > 1);\nSystem.out.println(x + \" \" + b + \" \" + c);","choices":["2 false false","3 false false","1 false false","2 false true","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"&& と || は短絡評価で、左辺だけで結果が決まれば右辺を評価しない。& と | は論理演算にも使えるが、両辺を必ず評価する。1つ目は左辺が false なので ++x は実行されず、2つ目の & では実行されて x が 2 になる。","topic":"演算子","mono":1},{"id":"basic-011","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int n = 0;\nif (n == 0 || 10 / n > 1) System.out.println(\"A\");\nif (n == 0 | 10 / n > 1) System.out.println(\"B\");","choices":["A だけ出力して正常終了","A と B を出力して正常終了","A を出力したあと ArithmeticException","何も出力せずに ArithmeticException","コンパイルエラー"],"answer":[2],"explain":"|| は左辺が true なら右辺を評価しないので、1つ目の if では 10 / n が実行されず A が出力される。| は短絡しないので右辺の 10 / n も実行され、整数の0除算で ArithmeticException が発生する。","topic":"演算子"},{"id":"basic-012","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"System.out.println(true ? 1 : 2.0);","choices":["1","1.0","2.0","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[1],"explain":"三項演算子の2番目と3番目が異なる数値型の場合、原則として算術演算と同じ規則で型がそろう。int と double なら double になるので、選ばれたのが 1 でも 1.0 と表示される。（例外：一方が char・byte・short で、もう一方がその型に収まる int の定数なら小さい方の型になる。false ? 'a' : 98 は b と表示される）","topic":"演算子","mono":1},{"id":"basic-013","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"System.out.println(7 / 2 + \" \" + -7 % 3 + \" \" + 7 % -3);","choices":["3 -1 1","3.5 -1 1","3 2 -2","3 -1 -1","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"int どうしの / は小数部を切り捨てる（7 / 2 は 3）。% の結果の符号は左辺（割られる数）の符号に一致するので、-7 % 3 は -1、7 % -3 は 1。% は + より優先順位が高いので、文字列連結の前に計算される。","topic":"演算子","mono":1},{"id":"basic-014","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int x = 2;\nif (x > 3)\n    System.out.print(\"A\");\n    System.out.print(\"B\");\nif (x > 10)\n    System.out.print(\"C\");\nelse\n    System.out.print(\"D\");","choices":["BD","D","ABD","B","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"波かっこを省略した if が支配するのは直後の1文だけ。インデントは意味を持たないので、print(\"B\") は if の外にあり常に実行される。x は 2 なので A は出ず、2つ目の if は else 側の D になる。","topic":"制御構文","mono":1},{"id":"basic-015","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int n = 2;\nswitch (n) {\n    case 1: System.out.print(\"A\");\n    case 2: System.out.print(\"B\");\n    case 3: System.out.print(\"C\"); break;\n    default: System.out.print(\"D\");\n}","choices":["B","BC","BCD","BD","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[1],"explain":"コロン形式の switch 文は、一致した case から break に出会うまで下へ順に実行し続ける（フォールスルー）。case 2 から入り、B、C と出力して case 3 の break で抜ける。","topic":"制御構文","mono":1},{"id":"basic-016","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int n = 1;\nswitch (n) {\n    case 1 -> System.out.print(\"A\");\n    case 2 -> System.out.print(\"B\");\n    default -> System.out.print(\"C\");\n}","choices":["A","AB","ABC","AC","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"アロー形式（case ... ->）の switch はフォールスルーしない。一致した case の右側だけを実行して switch を抜けるので、break は不要。switch 文でも switch 式でも同じ。","topic":"制御構文","mono":1},{"id":"basic-017","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int day = 3;\nString s = switch (day) {\n    case 1, 7 -> \"休日\";\n    case 2, 3, 4, 5, 6 -> {\n        String t = \"平日\";\n        yield t + day;\n    }\n    default -> \"不明\";\n};\nSystem.out.println(s);","choices":["平日3","平日","休日","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"アロー形式の右側をブロック { } にした場合、switch 式の値は yield で返す（return ではない）。case 1, 7 のようにカンマで複数の値をまとめられる。day は 3 なので2つ目のブロックに入り、\"平日\" + 3 が値になる。","topic":"制御構文","mono":1},{"id":"basic-018","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int n = 1;\nString s = switch (n) {\n    case 1 -> \"one\";\n    case 2 -> \"two\";\n};\nSystem.out.println(s);","choices":["one","null","2行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"switch 式は必ず値を返すので、とりうるすべての値を網羅していなければならない（網羅性）。int の値を case だけで網羅することはできないので、default が無いとコンパイルエラーになる。switch 文（値を返さない方）にはこの制約は無い。","topic":"制御構文"},{"id":"basic-019","type":"multi","q":"switch のかっこ内の式として、コンパイルエラーになるものを【すべて】選べ。","choices":["long v = 1L;\nswitch (v) { default: }","String s = \"a\";\nswitch (s) { default: }","char c = 'a';\nswitch (c) { default: }","double d = 1.0;\nswitch (d) { default: }","boolean b = true;\nswitch (b) { default: }","Integer i = 1;\nswitch (i) { default: }"],"answer":[0,3,4],"explain":"switch に使える基本データ型は int 以下の整数型（byte・short・char・int）だけ。これらのラッパー型、String、enum も使える。long・float・double・boolean は使えない。","topic":"制御構文","mono":1},{"id":"basic-020","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int i = 10;\nwhile (i < 5) {\n    System.out.print(\"W\");\n}\ndo {\n    System.out.print(\"D\");\n} while (i < 5);","choices":["D","WD","何も出力されない","無限ループになる","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"while は最初に条件を判定するので、条件が false なら本体は一度も実行されない。do-while は本体を実行してから条件を判定するので、条件が最初から false でも必ず1回は実行される。","topic":"制御構文","mono":1},{"id":"basic-021","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"for (int i = 0, j = 5; i < j; i++, j--) {\n    System.out.print(i + j + \" \");\n}","choices":["5 5 5","05 14 23","5 5 5 5","0 1 2","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"for の初期化部と更新部はカンマで複数書ける（初期化部で宣言できる型は1種類だけ）。i + j + \" \" は左から評価されるので、先に i + j が数値として足されてから文字列になる。i と j の和は常に 5 で、i < j の間の3回ループする。","topic":"制御構文","mono":1},{"id":"basic-022","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"outer:\nfor (int i = 0; i < 3; i++) {\n    for (int j = 0; j < 3; j++) {\n        if (j == 1) continue outer;\n        if (i == 2) break outer;\n        System.out.print(i + \"\" + j + \" \");\n    }\n}","choices":["00 10","00 10 20","00 01 10 11","00","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"ラベル付きの continue outer は内側のループを抜けて外側ループの次の周回へ進み、break outer は外側ループごと終了する。j が 1 になるたびに外側の次の i へ進み、i が 2 になった最初の j = 0 で全体が終わる。","topic":"制御構文","mono":1},{"id":"basic-023","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int[] a = {1, 2, 3};\nfor (int x : a) {\n    x *= 10;\n}\nfor (int x : a) {\n    System.out.print(x + \" \");\n}","choices":["1 2 3","10 20 30","0 0 0","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"拡張 for の変数 x には、配列の要素のコピーが入る。x を書き換えても配列の中身は変わらない。配列の要素を書き換えたいときは、添字を使う普通の for で a[i] に代入する。","topic":"制御構文","mono":1},{"id":"basic-024","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String s = \"java\";\ns.toUpperCase();\ns.concat(\"17\");\nSystem.out.println(s);","choices":["java","JAVA","JAVA17","java17","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"String は不変（イミュータブル）で、toUpperCase や concat は新しい String を返すだけで元の文字列は変えない。戻り値を受け取っていないので s は \"java\" のまま。変えたいなら s = s.toUpperCase(); のように代入し直す。","topic":"文字列","mono":1},{"id":"basic-025","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String a = \"hello\";\nString b = \"hel\" + \"lo\";\nString c = new String(\"hello\");\nString d = \"hel\";\nString e = d + \"lo\";\nSystem.out.println((a == b) + \" \" + (a == c) + \" \" + (a == e) + \" \" + a.equals(c));","choices":["true false false true","true true true true","false false false true","true false true true","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"== は参照（同じオブジェクトか）を比べ、equals は中身を比べる。\"hel\" + \"lo\" はリテラルどうしなのでコンパイル時に \"hello\" になり、プールの同じオブジェクトを指す。new String や、final でない変数を含む連結（d + \"lo\"）は実行時に新しいオブジェクトを作るので == は false。（d を final String d = \"hel\"; と宣言すると d + \"lo\" は定数式になり、a == e は true になる）","topic":"文字列","mono":1},{"id":"basic-026","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"StringBuilder sb1 = new StringBuilder(\"abc\");\nStringBuilder sb2 = new StringBuilder(\"abc\");\nSystem.out.println(sb1.equals(sb2) + \" \" + sb1.toString().equals(sb2.toString()));","choices":["false true","true true","true false","false false","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"StringBuilder は equals をオーバーライドしていないので、Object の equals（参照の比較）がそのまま使われる。中身が同じでも別オブジェクトなら false。中身を比べたいときは toString() で String にしてから equals するか、compareTo を使う。","topic":"文字列","mono":1},{"id":"basic-027","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"StringBuilder sb = new StringBuilder(\"12345\");\nsb.reverse();\nsb.insert(0, \"x\").delete(3, 5);\nSystem.out.println(sb);","choices":["x541","12345","x5421","x521","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"StringBuilder の append・insert・delete・reverse などの変更系メソッドは自分自身の中身を書き換え、戻り値も自分自身なので、戻り値を受け取らなくても変化は残る（String と逆）。ただし substring は新しい String を返すだけで中身は変えない。reverse で \"54321\"、insert(0, \"x\") で \"x54321\"、delete(3, 5) は添字 3 以上 5 未満を消すので \"x541\"。","topic":"文字列","mono":1},{"id":"basic-028","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String t = \"\"\"\n    ab\n      c\n    \"\"\";\nSystem.out.println(t.length());","choices":["7","5","6","9","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"テキストブロックは、閉じ側の \"\"\" の行を含め、空行以外の行のうち最も浅いインデントを基準に、共通の先頭空白を取り除く。中身は \"ab\\n  c\\n\"（c の前の空白2つと、c の行末の改行を含む）で 7 文字。閉じ側の \"\"\" を独立した行に置くと末尾に改行が付く。","topic":"文字列","mono":1},{"id":"basic-029","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String t = \"\"\"abc\"\"\";\nSystem.out.println(t);","choices":["abc","\"abc\"","1行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"テキストブロックの開き側の \"\"\" の後ろには（空白を除いて）何も書けず、すぐに改行しなければならない。中身は必ず次の行から始める。1行で書きたいなら普通の文字列リテラル \"abc\" を使う。","topic":"文字列"},{"id":"cls-001","type":"multi","q":"配列の宣言・生成として、コンパイルエラーになるものを【すべて】選べ。","choices":["int[] a = new int[3];","int a[] = {1, 2, 3};","int[] a = new int[];","int[3] a;","int[] a = new int[]{1, 2};","int[] a = new int[2]{1, 2};"],"answer":[2,3,5],"explain":"new で配列を作るとき、初期化子 {…} を付けないなら要素数が必須（new int[] だけは不可）。初期化子を付けるなら逆に要素数は書けない（new int[]{1, 2} は可、new int[2]{1, 2} は不可。要素数は初期化子の個数で決まる）。宣言側の [] に要素数は書けない。[] は型の後ろでも変数名の後ろでもよい。","topic":"配列とリスト","mono":1,"sub":"配列"},{"id":"cls-002","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String[] s = new String[2];\ndouble[] d = new double[2];\nboolean[] b = new boolean[2];\nSystem.out.println(s[0] + \" \" + d[1] + \" \" + b[0]);","choices":["null 0.0 false","（何も出ない） 0.0 false","null 0 false","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"new で作った配列の要素は、明示しなくても型ごとの既定値で初期化される。参照型は null、double は 0.0、boolean は false、int は 0。ローカル変数と違い、配列の要素は初期化なしで読んでもエラーにならない。","topic":"配列とリスト","mono":1,"sub":"配列"},{"id":"cls-003","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int[][] m = new int[3][];\nm[0] = new int[5];\nm[1] = new int[]{7, 8};\nSystem.out.println(m.length + \" \" + m[1].length);","choices":["3 2","5 2","3 5","2 3","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"多次元配列は「配列の配列」。m.length は1次元目の要素数（3）で、m[1].length はその中の配列の要素数（2）。2次元目の長さは行ごとにばらばらでよい。","topic":"配列とリスト","mono":1,"sub":"配列"},{"id":"cls-004","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int[][] m = new int[2][];\nSystem.out.println(m[1].length);","choices":["0 と表示される","2 と表示される","NullPointerException が発生する","コンパイルエラー"],"answer":[2],"explain":"new int[2][] は1次元目の配列だけを作る。その要素 m[0]・m[1] は int[] 型（参照型）なので既定値 null のままで、2次元目の配列はまだ無い。null に対して .length を読もうとするので実行時に NullPointerException になる。コンパイルは通る。","topic":"配列とリスト","sub":"配列"},{"id":"cls-005","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int[] a = {1, 2, 3};\nSystem.out.println(a.length());","choices":["3","2行目でコンパイルエラー","実行時に例外","2"],"answer":[1],"explain":"配列の長さは length フィールドで、メソッドではないので () を付けない。a.length() と書くとコンパイルエラー。String は length() メソッド、ArrayList は size() メソッドと、それぞれ書き方が違う。","topic":"配列とリスト","sub":"配列"},{"id":"cls-006","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int[] a = new int[3];\na[3] = 1;\nSystem.out.println(a[0]);","choices":["0 と表示される","1 と表示される","ArrayIndexOutOfBoundsException が発生する","コンパイルエラー"],"answer":[2],"explain":"要素数3の配列の添字は 0〜2。範囲外の添字はコンパイル時には検出されず、実行時に ArrayIndexOutOfBoundsException になる。","topic":"配列とリスト","sub":"配列"},{"id":"cls-007","type":"single","q":"int[] a = {1, 2}; の直後に System.out.println(a); を実行したときの説明として正しいものは？","choices":["[1, 2] と表示される","1 2 と表示される","[I@ のあとに16進数が続く文字列（実行ごとに変わりうる）が表示される","コンパイルエラーになる"],"answer":[2],"explain":"配列も Object を継承したオブジェクトで、toString() はオーバーライドされていない。そのため「型を表す記号（int 配列なら [I）＋ @ ＋ ハッシュコードの16進数」が表示される。中身を見たいときは java.util.Arrays.toString(a) を使う。","topic":"配列とリスト","sub":"配列"},{"id":"cls-008","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> list = new ArrayList<>();\n        list.add(10);\n        list.add(20);\n        list.add(30);\n        list.remove(1);\n        list.remove(Integer.valueOf(10));\n        System.out.println(list);\n    }\n}","choices":["[30]","[10]","[20, 30]","実行時に例外","コンパイルエラー"],"answer":[0],"explain":"List<Integer> の remove には remove(int index)（位置で削除）と remove(Object o)（値で削除）がある。int リテラルを渡すと remove(int) が選ばれ、添字 1（先頭から2番目）の 20 が消える。Integer.valueOf(10) は参照型（Integer）なので remove(Object) が選ばれ、値 10 が消えて [30] が残る。","topic":"配列とリスト","mono":1,"sub":"ArrayList"},{"id":"cls-009","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> list = new ArrayList<>();\n        list.add(\"A\");\n        list.add(\"B\");\n        list.add(0, \"C\");\n        list.set(1, \"D\");\n        System.out.println(list + \" \" + list.size());\n    }\n}","choices":["[C, D, B] 3","[C, A, B] 3","[D, A, B] 3","[C, D, A, B] 4","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"add(int, E) は指定位置に挿入して後ろをずらす（要素数が増える）。set(int, E) は指定位置を置き換える（要素数は変わらない）。[A, B] → add(0,\"C\") で [C, A, B] → set(1,\"D\") で [C, D, B]。要素数は size() で取る。","topic":"配列とリスト","mono":1,"sub":"ArrayList"},{"id":"cls-010","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> list = new ArrayList<>();\n        list.add(5);\n        list.remove(5);\n        System.out.println(list);\n    }\n}","choices":["[] と表示される","[5] と表示される","IndexOutOfBoundsException が発生する","コンパイルエラー"],"answer":[2],"explain":"list.remove(5) の 5 は int なので、値5の削除ではなく「添字5の要素を削除」する remove(int) が選ばれる（オートボクシングより完全一致が優先）。要素は1つしかないので IndexOutOfBoundsException。値で消したいなら remove(Integer.valueOf(5)) と書く。","topic":"配列とリスト","sub":"ArrayList"},{"id":"cls-011","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ（java.util は完全修飾名で書いている）。","choices":["java.util.List<int> a = new java.util.ArrayList<>();","java.util.List<Integer> a = new java.util.ArrayList<>();","java.util.ArrayList<String> a = new java.util.ArrayList<String>();","java.util.List<String> a = new java.util.ArrayList<>(); a.add(1);","java.util.List<Object> a = new java.util.ArrayList<String>();"],"answer":[0,3,4],"explain":"型引数に基本データ型（int など）は使えず、ラッパークラス（Integer）を使う。List<String> に int は追加できない。String が Object のサブクラスでも、List<Object> と ArrayList<String> の間に継承関係は無いので代入できない。右辺の <> は左辺から型を推論する（ダイヤモンド演算子）。","topic":"配列とリスト","mono":1,"sub":"ArrayList"},{"id":"cls-012","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Dog {\n    String name;\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Dog d1 = new Dog();\n        d1.name = \"A\";\n        Dog d2 = d1;\n        d2.name = \"B\";\n        System.out.println(d1.name);\n    }\n}","choices":["B","A","null","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"変数に入っているのはインスタンスそのものではなく参照（インスタンスの場所）。d2 = d1 は参照のコピーなので、d1 と d2 は同じインスタンスを指す。d2 経由で name を変えると d1 から見ても B になる。","topic":"クラスとメソッド","mono":1,"sub":"クラス"},{"id":"cls-013","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static int sign(int x) {\n        if (x > 0) {\n            return 1;\n        }\n    }\n    public static void main(String[] args) {\n        System.out.println(sign(5));\n    }\n}","choices":["1 と表示される","0 と表示される","6行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"戻り値の型が void でないメソッドは、どの経路でも return で値を返すか、例外を throw して終わらなければならない（最後の } まで流れ着いてはいけない）。x > 0 でない場合に return が無いので、メソッドの終わり（6行目）で missing return statement のコンパイルエラーになる。実行時の値は関係ない。","topic":"クラスとメソッド","sub":"メソッド"},{"id":"cls-014","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static void m(long x) { System.out.print(\"long \"); }\n    static void m(Integer x) { System.out.print(\"Integer \"); }\n    static void m(Object x) { System.out.print(\"Object \"); }\n    public static void main(String[] args) {\n        m(5);\n        m(5.0);\n    }\n}","choices":["long Object","Integer Object","long double","Integer Double","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"オーバーロードの呼び出しは「完全一致 → 拡大変換 → オートボクシング → 可変長引数」の順で探される。m(5) は int→long の拡大変換が見つかるので、ボクシングが要る Integer 版より優先される。m(5.0) は double を受け取る版も拡大先も無いので、Double にボクシングされ Object 版が選ばれる。","topic":"クラスとメソッド","mono":1,"sub":"オーバーロード"},{"id":"cls-015","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["class A { void m(int a) {} int m(int b) { return b; } }","class A { void m(int a) {} void m(long a) {} }","class A { void m(int a, String s) {} void m(String s, int a) {} }","class A { void m(int a) {} private void m(int b) {} }","class A { static void m(int a) {} void m(int a) {} }"],"answer":[0,3,4],"explain":"オーバーロードが成立するのは、引数の型・個数・並び順のどれかが違う場合だけ。戻り値の型、アクセス修飾子、static の有無、引数の変数名が違うだけでは同じシグネチャとみなされ、重複定義のコンパイルエラーになる。","topic":"クラスとメソッド","mono":1,"sub":"オーバーロード"},{"id":"cls-016","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Item {\n    String name;\n    Item(String name) {\n        this.name = name;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Item i = new Item();\n        System.out.println(i.name);\n    }\n}","choices":["null と表示される","空文字が表示される","10行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"デフォルトコンストラクタ（引数なし）は、クラスにコンストラクタが1つも書かれていないときだけコンパイラが自動で追加する。Item(String) を書いた時点で引数なしのコンストラクタは存在しなくなるので、new Item() はコンパイルエラー。必要なら Item() {} を自分で書く。","topic":"コンストラクタと初期化","sub":"コンストラクタ"},{"id":"cls-017","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class P {\n    P() {\n        this(\"x\");\n        System.out.print(\"A\");\n    }\n    P(String s) {\n        System.out.print(\"B\" + s);\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        new P();\n    }\n}","choices":["BxA","ABx","A","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"this(...) は同じクラスの別のコンストラクタを呼び出す。呼び出し先の P(String) が先に実行されて Bx を出力し、戻ってから残りの A を出力する。this(...) はコンストラクタの先頭にしか書けない。","topic":"コンストラクタと初期化","mono":1,"sub":"コンストラクタ"},{"id":"cls-018","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Parent {\n    Parent() { System.out.print(\"P\"); }\n}\n\nclass Child extends Parent {\n    Child() { System.out.print(\"C\"); }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        new Child();\n    }\n}","choices":["PC","CP","C","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"コンストラクタの先頭に this(...) も super(...) も書かなければ、コンパイラが super() を自動で挿入する。そのため子クラスのコンストラクタ本体より先に、親クラスのコンストラクタが実行される。","topic":"コンストラクタと初期化","mono":1,"sub":"コンストラクタ"},{"id":"cls-019","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Base {\n    Base(int n) { }\n}\n\nclass Sub extends Base {\n    Sub() {\n        System.out.println(\"sub\");\n        super(1);\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        new Sub();\n    }\n}","choices":["sub と表示される","コンパイルエラー","実行時に例外","何も表示されない"],"answer":[1],"explain":"super(...) と this(...) はコンストラクタの最初の文にしか書けない。8行目の super(1) は2文目なので、call to super must be first statement in constructor のコンパイルエラーになる。super(1); を1文目に移せば通り、sub と表示される。","topic":"コンストラクタと初期化","sub":"コンストラクタ"},{"id":"cls-020","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Item {\n    void Item() {\n        System.out.print(\"X\");\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        new Item();\n        System.out.print(\"Y\");\n    }\n}","choices":["Y","XY","X","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"戻り値の型（void）を書くと、クラス名と同じ名前でもコンストラクタではなく普通のメソッドになる。このクラスにはコンストラクタが書かれていないのでデフォルトコンストラクタが使われ、Item() メソッドは呼ばれない。クラス名と同名のメソッドはコンパイルエラーにならない。","topic":"コンストラクタと初期化","mono":1,"sub":"コンストラクタ"},{"id":"cls-021","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    int count = 0;\n    public static void main(String[] args) {\n        count++;\n        System.out.println(count);\n    }\n}","choices":["1 と表示される","0 と表示される","4行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"static メソッドはインスタンスが無くても動くので、そこから this に属するインスタンス変数・インスタンスメソッドを直接使えない（non-static variable cannot be referenced from a static context）。5行目の println(count) も同じ理由でエラーになる。使うなら new Main().count のようにインスタンスを作ってから参照する。","topic":"クラスとメソッド","sub":"static"},{"id":"cls-022","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Counter {\n    static int total = 0;\n    int own = 0;\n    Counter() {\n        total++;\n        own++;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Counter c1 = new Counter();\n        Counter c2 = new Counter();\n        Counter c3 = new Counter();\n        System.out.println(Counter.total + \" \" + c3.own);\n    }\n}","choices":["3 1","1 1","3 3","1 3","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"static 変数はクラスに1つだけあり、全インスタンスで共有される。インスタンス変数はインスタンスごとに別々に作られる。3回 new したので total は 3、c3 の own は c3 自身の 1。","topic":"クラスとメソッド","mono":1,"sub":"static"},{"id":"cls-023","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Account {\n    private int balance = 100;\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Account a = new Account();\n        System.out.println(a.balance);\n    }\n}","choices":["100 と表示される","0 と表示される","8行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"private のメンバは、宣言したクラスの中（入れ子クラスなら、それを囲むトップレベルクラスの中）からしか使えない。同じファイル・同じパッケージの別クラス（Main）からでもアクセスできない。外から読ませたいなら public な getter を用意する。","topic":"クラスとメソッド","sub":"アクセス修飾子"},{"id":"cls-024","type":"single","q":"アクセス修飾子の説明として正しいものは？","choices":["無指定（パッケージプライベート）のメンバは、別パッケージのサブクラスからもアクセスできる","protected のメンバは、同じパッケージのクラスと、別パッケージのサブクラスからアクセスできる","private のメンバは、同じパッケージのクラスからならアクセスできる","公開範囲の広い順に並べると public ＞ 無指定 ＞ protected ＞ private"],"answer":[1],"explain":"公開範囲は広い順に public（どこからでも）＞ protected（同一パッケージ＋別パッケージのサブクラス）＞ 無指定（同一パッケージのみ）＞ private（同一クラスのみ）。protected は無指定より広い。","topic":"クラスとメソッド","sub":"アクセス修飾子"},{"id":"cls-025","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Account {\n    private int balance;\n    public void deposit(int amount) {\n        if (amount > 0) {\n            balance += amount;\n        }\n    }\n    public int getBalance() {\n        return balance;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Account a = new Account();\n        a.deposit(100);\n        a.deposit(-50);\n        System.out.println(a.getBalance());\n    }\n}","choices":["100","50","150","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"フィールドを private にして、値の変更をメソッド経由に限るのがカプセル化。deposit は 0 以下の金額をはじくので、-50 は反映されず残高は 100 のまま。フィールドが外から直接書き換えられないので、こうしたチェックを必ず通せる。","topic":"クラスとメソッド","mono":1,"sub":"カプセル化"},{"id":"cls-026","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"boolean flag = true;\nint x;\nif (flag) {\n    x = 1;\n}\nSystem.out.println(x);","choices":["1 と表示される","0 と表示される","6行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"ローカル変数には既定値が無く、読む前に確実に代入されていなければならない。flag は final でない変数なので、コンパイラは if の中を通らない可能性があると判断し、variable x might not have been initialized のエラーにする。フィールドや配列の要素なら既定値（0）が入る。","topic":"クラスとメソッド","sub":"スコープ"},{"id":"cls-027","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int sum = 0;\nfor (int i = 0; i < 3; i++) {\n    sum += i;\n}\nSystem.out.println(i);","choices":["3 と表示される","2 と表示される","5行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"for 文の () の中で宣言した変数のスコープは、その for 文の中だけ。ループを抜けた後の i は存在しないので cannot find symbol のコンパイルエラーになる。ループ後も使いたいなら for の外で宣言する。","topic":"クラスとメソッド","sub":"スコープ"},{"id":"cls-028","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static void change(int[] arr, int n) {\n        arr[0] = 99;\n        n = 99;\n        arr = new int[]{0};\n        arr[0] = -1;\n    }\n    public static void main(String[] args) {\n        int[] a = {1};\n        int n = 1;\n        change(a, n);\n        System.out.println(a[0] + \" \" + n);\n    }\n}","choices":["99 1","99 99","-1 1","1 1","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"Java の引数は常に値渡し。int は値そのもののコピーなので n を変えても呼び出し元は 1 のまま。配列は参照の値がコピーされるので arr[0] = 99 は同じ配列を変える。arr に新しい配列を代入した後の変更は、コピーした参照を差し替えただけなので呼び出し元に届かない。","topic":"クラスとメソッド","mono":1,"sub":"値渡し"},{"id":"cls-029","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static void edit(StringBuilder sb) {\n        sb.append(\"B\");\n        sb = new StringBuilder(\"X\");\n        sb.append(\"Y\");\n    }\n    public static void main(String[] args) {\n        StringBuilder sb = new StringBuilder(\"A\");\n        edit(sb);\n        System.out.println(sb);\n    }\n}","choices":["AB","A","XY","ABXY","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"sb には参照のコピーが渡るので、append(\"B\") は呼び出し元と同じオブジェクトを変更する。その後 sb = new StringBuilder(\"X\") で引数の変数が別オブジェクトを指すようになり、以降の変更は呼び出し元に影響しない。","topic":"クラスとメソッド","mono":1,"sub":"値渡し"},{"id":"oop-001","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Parent {\n    String name = \"P\";\n    String getName() { return name; }\n}\nclass Child extends Parent {\n    String name = \"C\";\n    String getName() { return name; }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Parent p = new Child();\n        System.out.println(p.name + \" \" + p.getName());\n    }\n}","choices":["P P","C C","P C","C P","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[2],"explain":"フィールドはオーバーライドされず、どのフィールドを読むかは変数の型（コンパイル時の型）で決まる。p は Parent 型なので p.name は Parent の \"P\"。一方メソッドはオーバーライドされるので、実行時のオブジェクト（Child）の getName() が呼ばれ \"C\" になる。","topic":"継承とポリモーフィズム","mono":1,"sub":"継承"},{"id":"oop-002","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Parent {\n    public void hello() { System.out.println(\"Parent\"); }\n}\nclass Child extends Parent {\n    @Override\n    protected void hello() { System.out.println(\"Child\"); }\n}\npublic class Main {\n    public static void main(String[] args) {\n        new Child().hello();\n    }\n}","choices":["Child と表示される","Parent と表示される","6行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"オーバーライドでアクセス修飾子を狭めることはできない（public → protected は狭める方向）。同じか広くするのは可。広さは public > protected > 無指定 > private の順。","topic":"継承とポリモーフィズム","sub":"継承"},{"id":"oop-003","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class A {\n    static void m() { System.out.println(\"A\"); }\n}\nclass B extends A {\n    void m() { System.out.println(\"B\"); }\n}\npublic class Main {\n    public static void main(String[] args) {\n        new B().m();\n    }\n}","choices":["A と表示される","B と表示される","5行目でコンパイルエラー","9行目でコンパイルエラー"],"answer":[2],"explain":"親の static メソッドと同じシグネチャのインスタンスメソッドを子で定義するとコンパイルエラー（逆に、親のインスタンスメソッドを子で static にしてもエラー）。static とインスタンスの間ではオーバーライドも隠蔽も成り立たない。","topic":"継承とポリモーフィズム","sub":"継承"},{"id":"oop-004","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class A {\n    static String m() { return \"A\"; }\n}\nclass B extends A {\n    static String m() { return \"B\"; }\n}\npublic class Main {\n    public static void main(String[] args) {\n        A x = new B();\n        B y = new B();\n        System.out.println(x.m() + \" \" + y.m());\n    }\n}","choices":["A B","B B","A A","B A","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"static メソッドはオーバーライドされず、子で同じシグネチャの static メソッドを書くと「隠蔽」になる。隠蔽されたメソッドはオブジェクトの型ではなく変数（参照）の型で選ばれるので、A 型の x では A.m()、B 型の y では B.m() が呼ばれる。","topic":"継承とポリモーフィズム","mono":1,"sub":"継承"},{"id":"oop-005","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["class A { void m() {} } class B extends A { private void m() {} }","class A { protected void m() {} } class B extends A { public void m() {} }","class A { static void m() {} } class B extends A { static void m() {} }","class A { void m() {} } class B extends A { static void m() {} }","class A { Object m() { return null; } } class B extends A { String m() { return null; } }"],"answer":[0,3],"explain":"オーバーライドではアクセスを狭められない（無指定 → private は不可、protected → public は可）。インスタンスメソッドを static で再定義するのは不可、static 同士なら隠蔽として可。戻り値の型はサブクラス型にしてよい（共変戻り値）。","topic":"継承とポリモーフィズム","mono":1,"sub":"継承"},{"id":"oop-006","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Parent {\n    Parent() { show(); }\n    void show() { System.out.println(\"P\"); }\n}\nclass Child extends Parent {\n    String msg = \"C\";\n    @Override\n    void show() { System.out.println(msg); }\n}\npublic class Main {\n    public static void main(String[] args) {\n        new Child();\n    }\n}","choices":["P","C","null","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[2],"explain":"親のコンストラクタから呼んだメソッドも、オーバーライドされていれば実行時のオブジェクト（Child）のものが呼ばれる。ただしその時点では親のコンストラクタが走っている最中で、子のフィールド初期化（msg = \"C\"）はまだ行われていないため、msg は既定値の null。","topic":"継承とポリモーフィズム","mono":1,"sub":"ポリモーフィズム"},{"id":"oop-007","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Animal {\n    void sound() { System.out.println(\"...\"); }\n}\nclass Dog extends Animal {\n    void bark() { System.out.println(\"Woof\"); }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Animal a = new Dog();\n        a.bark();\n    }\n}","choices":["Woof と表示される","... と表示される","10行目でコンパイルエラー","実行時に ClassCastException"],"answer":[2],"explain":"呼べるメソッドはコンパイル時に変数の型で決まる。a は Animal 型で、Animal に bark() は無いのでコンパイルエラー。中身が Dog でも関係ない。呼ぶには ((Dog) a).bark() のようにキャストする。","topic":"継承とポリモーフィズム","sub":"ポリモーフィズム"},{"id":"oop-008","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class A { String name() { return \"A\"; } }\nclass B extends A { String name() { return \"B\"; } }\nclass C extends B { }\npublic class Main {\n    public static void main(String[] args) {\n        A[] arr = { new A(), new B(), new C() };\n        String s = \"\";\n        for (A a : arr) s += a.name();\n        System.out.println(s);\n    }\n}","choices":["AAA","ABC","ABB","ACC","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[2],"explain":"オーバーライドされたメソッドは、変数や配列の型ではなく、実際に new したオブジェクトの型で選ばれる。C は name() をオーバーライドしていないので、親の B の name() が使われる。","topic":"継承とポリモーフィズム","mono":1,"sub":"ポリモーフィズム"},{"id":"oop-009","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Animal { }\nclass Dog extends Animal { }\nclass Cat extends Animal { }\npublic class Main {\n    public static void main(String[] args) {\n        Animal a = new Dog();\n        Cat c = (Cat) a;\n        System.out.println(\"cat\");\n    }\n}","choices":["cat と表示される","7行目でコンパイルエラー","実行時に ClassCastException が発生する","何も表示されない"],"answer":[2],"explain":"Animal から Cat へのダウンキャストは継承関係があるのでコンパイルは通る。しかし実体は Dog なので、実行時に ClassCastException になる。事前に a instanceof Cat で確かめるのが定石。","topic":"継承とポリモーフィズム","sub":"キャスト"},{"id":"oop-010","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"Integer i = 7;\nString s = (String) i;\nSystem.out.println(s);","choices":["7 と表示される","2行目でコンパイルエラー","実行時に ClassCastException が発生する","コンパイルは通るが何も表示されない"],"answer":[1],"explain":"Integer と String はどちらもクラスで、互いに親子（継承）関係が無い。クラス型どうしのキャストは、一方が他方のサブクラスでなければコンパイル時にエラーになる（incompatible types）。final かどうかは関係ない（兄弟クラスの Dog → Cat も同じエラー）。Object 型の変数に入れてからキャストすれば、コンパイルは通り実行時に ClassCastException となる。","topic":"継承とポリモーフィズム","sub":"キャスト"},{"id":"oop-011","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static String f(Object o) {\n        if (o instanceof String s && s.length() > 3) {\n            return String.valueOf(s.length());\n        }\n        return o.toString();\n    }\n    public static void main(String[] args) {\n        System.out.println(f(\"Hello\") + \" \" + f(3));\n    }\n}","choices":["5 3","Hello 3","実行時に ClassCastException が発生する","コンパイルエラー"],"answer":[0],"explain":"パターンマッチング instanceof（o instanceof String s）は、判定が true のときだけ変数 s に型変換済みの値を入れる。&& の右側では s が使える。\"Hello\" は長さ 5 なので \"5\"。Integer は String ではないので if の条件が false になり、6行目の return o.toString() で \"3\" が返る。","topic":"継承とポリモーフィズム","mono":1,"sub":"キャスト"},{"id":"oop-012","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"Object o = \"abc\";\nif (o instanceof String s || s.isEmpty()) {\n    System.out.println(true);\n} else {\n    System.out.println(false);\n}","choices":["true と表示される","false と表示される","2行目でコンパイルエラー","実行時に NullPointerException"],"answer":[2],"explain":"パターン変数 s は「確実にマッチした」ときだけ使える。|| の右側は左側が false のとき（＝マッチしなかったとき）に評価されるので、そこでは s はスコープに無くコンパイルエラー。&& の右側なら使える。","topic":"継承とポリモーフィズム","sub":"キャスト"},{"id":"oop-013","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Item {\n    int id;\n    Item(int id) { this.id = id; }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Item a = new Item(1);\n        Item b = new Item(1);\n        Item c = a;\n        System.out.println(a.equals(b) + \" \" + a.equals(c));\n    }\n}","choices":["true true","false true","false false","true false","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[1],"explain":"equals をオーバーライドしていないクラスでは、Object の equals がそのまま使われ、中身は == と同じ（同じオブジェクトかどうか）。a と b は別々に new しているので false、c は a と同じオブジェクトを指すので true。値で比べたければ自分で equals を書く（record なら自動で値比較になる）。","topic":"継承とポリモーフィズム","mono":1,"sub":"Object"},{"id":"oop-014","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Item {\n    String toString() { return \"Item\"; }\n}\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(new Item());\n    }\n}","choices":["Item と表示される","Item@ に続くハッシュ値が表示される","2行目でコンパイルエラー","何も表示されない"],"answer":[2],"explain":"Object の toString() は public。これをオーバーライドするときに public を付け忘れると、アクセスを狭めたことになりコンパイルエラー。equals・hashCode も同じく public で書く必要がある。","topic":"継承とポリモーフィズム","sub":"Object"},{"id":"oop-015","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"abstract class Shape {\n    abstract String name();\n}\nclass Circle extends Shape { String name() { return \"circle\"; } }\npublic class Main {\n    public static void main(String[] args) {\n        Shape s = new Circle();\n        Shape t = new Shape();\n        System.out.println(s.name());\n    }\n}","choices":["circle と表示される","7行目でコンパイルエラー","8行目でコンパイルエラー","実行時に InstantiationException"],"answer":[2],"explain":"抽象クラスは new できない（8行目がエラー）。ただし型として使うことはでき、7行目の Shape s = new Circle(); のように抽象クラス型の変数にサブクラスのオブジェクトを入れるのは問題ない。","topic":"抽象クラスとインターフェース","sub":"抽象クラス"},{"id":"oop-016","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"abstract class Base {\n    Base() { System.out.print(\"Base \"); }\n    abstract void run();\n}\nclass Dog extends Base {\n    Dog() { System.out.print(\"Dog\"); }\n    void run() { }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Base b = new Dog();\n        System.out.println();\n    }\n}","choices":["Dog","Base Dog","Dog Base","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[1],"explain":"抽象クラスも普通のクラスと同じくコンストラクタを持てる。new はできないが、サブクラスのコンストラクタの先頭で super() として呼ばれる。そのため Base → Dog の順に表示される。","topic":"抽象クラスとインターフェース","mono":1,"sub":"抽象クラス"},{"id":"oop-017","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"abstract class Task {\n    abstract void run();\n}\nclass Job extends Task {\n}\npublic class Main {\n    public static void main(String[] args) {\n        Task t = new Job();\n    }\n}","choices":["何も表示されない","4行目でコンパイルエラー","8行目でコンパイルエラー","実行時に AbstractMethodError"],"answer":[1],"explain":"抽象メソッドを持つ抽象クラスを継承した具象クラスは、すべての抽象メソッドを実装しなければならない。実装しないなら、そのクラス自身も abstract にする必要がある。エラーはクラス宣言の行（4行目）で出る。","topic":"抽象クラスとインターフェース","sub":"抽象クラス"},{"id":"oop-018","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"interface Greeter {\n    void greet();\n}\nclass Hello implements Greeter {\n    void greet() { System.out.println(\"Hi\"); }\n}\npublic class Main {\n    public static void main(String[] args) {\n        new Hello().greet();\n    }\n}","choices":["Hi と表示される","2行目でコンパイルエラー","5行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"インターフェースの抽象メソッドは、書かなくても暗黙に public abstract。実装クラス側で public を省略すると「無指定」になり、アクセスを狭めたことになってコンパイルエラー。実装側では必ず public を付ける。","topic":"抽象クラスとインターフェース","sub":"インターフェース"},{"id":"oop-019","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"interface A {\n    default void hello() { System.out.println(\"A\"); }\n}\ninterface B {\n    default void hello() { System.out.println(\"B\"); }\n}\nclass C implements A, B {\n}\npublic class Main {\n    public static void main(String[] args) {\n        new C().hello();\n    }\n}","choices":["A と表示される","B と表示される","7行目でコンパイルエラー","11行目でコンパイルエラー"],"answer":[2],"explain":"2つのインターフェースに同じシグネチャの default メソッドがあり、どちらも実装するクラスでオーバーライドしないと、どちらを使うか決まらずコンパイルエラーになる。エラーはクラス宣言の行に出る。C で hello() をオーバーライドすれば解決する。","topic":"抽象クラスとインターフェース","sub":"インターフェース"},{"id":"oop-020","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"interface A {\n    default void hello() { System.out.print(\"A\"); }\n}\ninterface B {\n    default void hello() { System.out.print(\"B\"); }\n}\nclass C implements A, B {\n    public void hello() {\n        B.super.hello();\n        A.super.hello();\n    }\n}\npublic class Main {\n    public static void main(String[] args) {\n        new C().hello();\n        System.out.println();\n    }\n}","choices":["A","B","BA","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[2],"explain":"同名の default メソッドが衝突したときは、実装クラスでオーバーライドして解決する。その中で特定のインターフェースの default を呼ぶには インターフェース名.super.メソッド名() と書く。ここでは B → A の順に呼んでいる。","topic":"抽象クラスとインターフェース","mono":1,"sub":"インターフェース"},{"id":"oop-021","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"interface Tool {\n    static void util() { System.out.println(\"util\"); }\n}\nclass Impl implements Tool {\n}\npublic class Main {\n    public static void main(String[] args) {\n        Tool.util();\n        Impl.util();\n    }\n}","choices":["util と2回表示される","8行目でコンパイルエラー","9行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"インターフェースの static メソッドは継承されず、外からは「インターフェース名.メソッド名()」でしか呼べない。実装クラス名（Impl.util()）や実装クラスのインスタンス経由では呼べない。クラスの static メソッドがサブクラス名で呼べるのとは違う点に注意。","topic":"抽象クラスとインターフェース","sub":"インターフェース"},{"id":"oop-022","type":"multi","q":"次のインターフェース宣言のうち、コンパイルエラーになるものを【すべて】選べ。","choices":["interface I { private void helper() {} }","interface I { private static int calc() { return 1; } }","interface I { protected void m(); }","interface I { default void m(); }","interface I { final void m(); }","interface I { static void m() {} }"],"answer":[2,3,4],"explain":"インターフェースには private メソッド（Java 9〜、static も可）と static メソッドを本体付きで書ける。protected は付けられない。default メソッドは本体が必須。final はオーバーライドさせない修飾子なので、実装されることが前提のインターフェースのメソッドには付けられない。","topic":"抽象クラスとインターフェース","mono":1,"sub":"インターフェース"},{"id":"oop-023","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"interface Config {\n    int MAX = 10;\n}\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(Config.MAX);\n        Config.MAX = 11;\n    }\n}","choices":["10 と表示される","11 と表示される","7行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"インターフェースに書いたフィールドは、暗黙に public static final（定数）になる。したがって再代入しようとするとコンパイルエラー。読むだけなら Config.MAX で使える。","topic":"抽象クラスとインターフェース","sub":"インターフェース"},{"id":"oop-024","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"sealed class Shape permits Circle { }\nfinal class Circle extends Shape { }\nnon-sealed class Square extends Shape { }\nclass Tile extends Square { }","choices":["コンパイルは成功する","3行目でコンパイルエラー","4行目でコンパイルエラー","3行目と4行目の両方でコンパイルエラー"],"answer":[1],"explain":"sealed クラスを継承できるのは permits に書いたクラスだけ。Square は permits に無いので、Square を宣言した3行目がエラーになる（原因の行）。Tile は non-sealed の Square を普通に継承しているだけなので、Tile の行自体はエラーにならない。","topic":"sealed・record・enum","sub":"sealed"},{"id":"oop-025","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"sealed class Shape permits Circle { }\nclass Circle extends Shape { }\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(\"Circle\");\n    }\n}","choices":["Circle と表示される","1行目でコンパイルエラー","2行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"sealed クラスの直接のサブクラスは、final・sealed・non-sealed のどれか1つを必ず付けなければならない。何も付けていない Circle の行がコンパイルエラーになる。","topic":"sealed・record・enum","sub":"sealed"},{"id":"oop-026","type":"multi","q":"コンパイルが通るものを【すべて】選べ。","choices":["sealed interface S permits T {} final class T implements S {}","sealed interface S permits T {} non-sealed interface T extends S {}","sealed interface S permits T {} final interface T extends S {}","sealed interface S permits T {} record T(int x) implements S {}","sealed interface S permits T {} interface T extends S {}"],"answer":[0,1,3],"explain":"sealed インターフェースのサブ型がクラスなら final・sealed・non-sealed の3択、インターフェースなら sealed・non-sealed の2択（インターフェースは final にできない）。record は暗黙に final なので、修飾子無しでそのまま許可されたサブ型になれる。","topic":"sealed・record・enum","mono":1,"sub":"sealed"},{"id":"oop-027","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"record Point(int x, int y) { }\npublic class Main {\n    public static void main(String[] args) {\n        Point a = new Point(1, 2);\n        Point b = new Point(1, 2);\n        System.out.println(a.x() + \" \" + a.equals(b));\n    }\n}","choices":["1 true","1 false","Point[x=1, y=2] true","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"record のアクセサはフィールド名そのまま（getX() ではなく x()）。equals は自動生成され、全コンポーネントの値が等しければ true になる。別々に new しても値が同じなので true。","topic":"sealed・record・enum","mono":1,"sub":"record"},{"id":"oop-028","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"record User(String name) { }\npublic class Main {\n    public static void main(String[] args) {\n        User u = new User(\"Tom\");\n        System.out.println(u.getName());\n    }\n}","choices":["Tom と表示される","5行目でコンパイルエラー","実行時に例外","null と表示される"],"answer":[1],"explain":"record のアクセサ名はコンポーネント名と同じ name() で、getName() は自動では作られない。存在しないメソッドを呼んでいるのでコンパイルエラー。","topic":"sealed・record・enum","sub":"record"},{"id":"oop-029","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"record Range(int min, int max) {\n    Range {\n        if (min < 0) min = 0;\n    }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Range r = new Range(-5, 3);\n        System.out.println(r.min() + \" \" + r.max());\n    }\n}","choices":["-5 3","0 3","0 0","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[1],"explain":"コンパクトコンストラクタ（引数リストを書かない形）では、引数を検証・加工でき、本体の最後で自動的にフィールドへ代入される。ここで this.min = ... と書くとエラーになるので、引数（min）自体を書き換える。","topic":"sealed・record・enum","mono":1,"sub":"record"},{"id":"oop-030","type":"multi","q":"コンパイルが通るものを【すべて】選べ。","choices":["record P(int x) { static int count; }","record P(int x) { int y; }","record P(int x) { P { if (x < 0) throw new IllegalArgumentException(); } }","record P(int x) extends Object { }","record P(int x) implements Comparable<P> { public int compareTo(P o) { return 0; } }"],"answer":[0,2,4],"explain":"record にはインスタンスフィールドを追加できない（static フィールドは可）。record は暗黙に java.lang.Record を継承しているので extends は書けないが、implements でインターフェースは実装できる。コンパクトコンストラクタで検証して例外を投げるのは典型的な使い方。","topic":"sealed・record・enum","mono":1,"sub":"record"},{"id":"oop-031","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"record Money(int amount) { }\nclass Yen extends Money { }","choices":["コンパイルは成功する","1行目でコンパイルエラー","2行目でコンパイルエラー","実行時に例外"],"answer":[2],"explain":"record は暗黙に final なので、ほかのクラスが record を継承（extends）することはできない。abstract を付けることもできない。","topic":"sealed・record・enum","sub":"record"},{"id":"oop-032","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"enum Season { SPRING, SUMMER, WINTER }\npublic class Main {\n    public static void main(String[] args) {\n        Season s = Season.valueOf(\"SUMMER\");\n        System.out.println(Season.values().length + \" \" + s.ordinal() + \" \" + s);\n    }\n}","choices":["3 2 SUMMER","3 1 SUMMER","4 1 SUMMER","3 1 summer","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[1],"explain":"values() は定数を宣言順に並べた配列を返す。ordinal() は宣言順の番号で 0 始まりなので、SUMMER は 1。name() は宣言したとおりの名前を返し、toString をオーバーライドしていなければ println も同じ名前を出す。","topic":"sealed・record・enum","mono":1,"sub":"enum"},{"id":"oop-033","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"enum Coin {\n    YEN(1), DOLLAR(100);\n    private final int value;\n    public Coin(int value) { this.value = value; }\n    int value() { return value; }\n}\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(Coin.DOLLAR.value());\n    }\n}","choices":["100 と表示される","3行目でコンパイルエラー","4行目でコンパイルエラー","9行目でコンパイルエラー"],"answer":[2],"explain":"enum のコンストラクタは暗黙に private で、public や protected を付けるとコンパイルエラー（private を明示するのは可）。enum は外からも中からも new できない（インスタンスは宣言した定数だけ）。","topic":"sealed・record・enum","sub":"enum"},{"id":"oop-034","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"enum Color {\n    RED(\"R\"), GREEN(\"G\"), BLUE(\"B\");\n    Color(String s) { System.out.print(\" \" + s); }\n}\npublic class Main {\n    public static void main(String[] args) {\n        System.out.print(\"start\");\n        Color c = Color.RED;\n        System.out.println();\n    }\n}","choices":["R start","start R","R G B start","start R G B","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[3],"explain":"enum の定数はすべて、enum が初めて使われたときに（宣言順に）まとめて1回ずつ生成される。Color.RED を使った時点で RED・GREEN・BLUE の3つのコンストラクタが走る。main の先頭の \"start\" はそれより前に出る。","topic":"sealed・record・enum","mono":1,"sub":"enum"},{"id":"oop-035","type":"single","q":"パッケージ p1 のクラス A に protected void m() がある。パッケージ p2 のクラス B が A を継承している。B の中で書いたときに正しいものはどれか。","choices":["this.m(); は呼べるが、new A().m(); は呼べない","this.m(); も new A().m(); も呼べる","this.m(); も new A().m(); も呼べない","B が public クラスなら両方呼べる"],"answer":[0],"explain":"別パッケージのサブクラスから protected メンバにアクセスできるのは、継承した自分自身（this や B 型の参照）経由の場合に限られる。親クラス A のインスタンスを new して、その参照経由で呼ぶことはできない。同じパッケージ内なら protected はどこからでも使える。","topic":"継承とポリモーフィズム","sub":"継承"},{"id":"exl-001","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static int f() {\n        try {\n            System.out.println(\"A\");\n            return 1;\n        } finally {\n            System.out.println(\"B\");\n        }\n    }\n    public static void main(String[] args) {\n        System.out.println(f());\n    }\n}","choices":["A\n1","A\nB\n1","A\n1\nB","B\nA\n1","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[1],"explain":"try の中で return しても、メソッドを抜ける前に必ず finally が実行される（System.exit() で JVM ごと終了した場合を除く）。戻り値 1 は finally の実行前に確定しており、呼び出し側で表示されるのは finally の後。したがって A → B → 1 の順になる。","topic":"例外処理","mono":1},{"id":"exl-002","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static int f() {\n        int x = 1;\n        try {\n            throw new RuntimeException();\n        } catch (RuntimeException e) {\n            x = 2;\n            return x;\n        } finally {\n            x = 3;\n        }\n    }\n    public static void main(String[] args) {\n        System.out.println(f());\n    }\n}","choices":["1","2","3","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[1],"explain":"catch の return x で戻り値 2 がその時点で確定する。finally で変数 x に 3 を代入し直しても、退避済みの戻り値 2 は変わらない（参照型でも同じ。ただし参照先のオブジェクトの中身を finally で書き換えると、その変更は呼び出し元から見える）。finally の中に return が無い限り、戻り値は変わらない。","topic":"例外処理","mono":1},{"id":"exl-003","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static String f() {\n        try {\n            throw new RuntimeException(\"try\");\n        } finally {\n            return \"finally\";\n        }\n    }\n    public static void main(String[] args) {\n        System.out.println(f());\n    }\n}","choices":["try","finally","try\nfinally","実行時に RuntimeException がスローされる","コンパイルエラー"],"answer":[1],"explain":"finally に return を書くと、try や catch で決まった戻り値だけでなく、スロー中の例外まで握りつぶして finally の値で上書きする。ここでは try で例外が発生しているが、finally の return \"finally\" が勝つので例外は呼び出し側に届かない。コンパイルは通るが、避けるべき書き方。","topic":"例外処理","mono":1},{"id":"exl-004","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"try {\n    int[] a = new int[1];\n    a[1] = 5;\n} catch (Exception e) {\n    System.out.println(\"E\");\n} catch (ArrayIndexOutOfBoundsException e) {\n    System.out.println(\"A\");\n}","choices":["E と表示される","A と表示される","6行目でコンパイルエラー","ArrayIndexOutOfBoundsException がスローされる"],"answer":[2],"explain":"catch は上から順に照合されるため、スーパークラス（Exception）の後にサブクラス（ArrayIndexOutOfBoundsException）を書くと、後ろの catch には絶対に到達しない。到達不能な catch はコンパイルエラーになる。サブクラスの catch を先に書くこと。","topic":"例外処理"},{"id":"exl-005","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static void check() {\n        throw new Exception(\"NG\");\n    }\n    public static void main(String[] args) {\n        System.out.println(\"start\");\n        check();\n    }\n}","choices":["start と表示される","3行目でコンパイルエラー","7行目でコンパイルエラー","実行時に Exception がスローされる"],"answer":[1],"explain":"Exception は検査例外（RuntimeException のサブクラスではない）なので、スローするメソッドは try-catch で処理するか throws Exception を宣言しなければならない。どちらも無いので throw 文の行でコンパイルエラーになる（unreported exception）。","topic":"例外処理"},{"id":"exl-006","type":"multi","q":"コンパイルが通るものを【すべて】選べ。","choices":["class A { void m() { throw new RuntimeException(); } }","class A { void m() { throw new Exception(); } }","class A { void m() throws Exception { throw new java.io.IOException(); } }","class A { void m() { throw new Error(); } }","class A { void m() { throw new java.io.IOException(); } }"],"answer":[0,2,3],"explain":"RuntimeException とそのサブクラス、Error とそのサブクラスは非検査例外で、throws 宣言も catch も不要。Exception や IOException は検査例外なので、throws か catch が必須。throws にはスローする例外のスーパークラスを書いてもよい（IOException に対して throws Exception は OK）。","topic":"例外処理","mono":1},{"id":"exl-007","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"try {\n    System.out.println(\"ok\");\n} catch (java.io.IOException e) {\n    System.out.println(\"io\");\n}","choices":["ok と表示される","何も表示されない","3行目でコンパイルエラー","実行時に IOException がスローされる"],"answer":[2],"explain":"IOException のような検査例外は、try ブロックの中でスローされる可能性が無いと catch できず、コンパイルエラーになる（exception is never thrown in body of corresponding try statement）。一方、Exception や RuntimeException の catch は try の中身に関係なく書ける。","topic":"例外処理"},{"id":"exl-008","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"try {\n    Integer.parseInt(\"x\");\n} catch (NumberFormatException | IllegalArgumentException e) {\n    System.out.println(e.getClass().getSimpleName());\n}","choices":["NumberFormatException と表示される","RuntimeException と表示される","3行目でコンパイルエラー","実行時に NumberFormatException がスローされる"],"answer":[2],"explain":"マルチキャッチ（|）で並べる例外同士に継承関係があってはならない。NumberFormatException は IllegalArgumentException のサブクラスなので、まとめて書くとコンパイルエラー。IllegalArgumentException だけを書けば両方をキャッチできる。","topic":"例外処理"},{"id":"exl-009","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"try {\n    int x = 10 / 0;\n} catch (ArithmeticException | NullPointerException e) {\n    e = null;\n    System.out.println(e);\n}","choices":["ArithmeticException と表示される","null と表示される","4行目でコンパイルエラー","実行時に ArithmeticException がスローされる"],"answer":[2],"explain":"マルチキャッチの変数 e は暗黙的に final なので、別の値を代入できない。単一の型の catch（catch (ArithmeticException e)）なら再代入はコンパイルできるが、推奨されない。","topic":"例外処理"},{"id":"exl-010","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Res implements AutoCloseable {\n    private final String name;\n    Res(String name) { this.name = name; }\n    public void close() { System.out.println(\"close \" + name); }\n}\npublic class Main {\n    public static void main(String[] args) {\n        try (Res a = new Res(\"A\"); Res b = new Res(\"B\")) {\n            System.out.println(\"body\");\n            throw new IllegalStateException();\n        } catch (IllegalStateException e) {\n            System.out.println(\"catch\");\n        }\n    }\n}","choices":["body\nclose A\nclose B\ncatch","body\nclose B\nclose A\ncatch","body\ncatch\nclose B\nclose A","body\ncatch\nclose A\nclose B","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[1],"explain":"try-with-resources のリソースは、宣言した順と逆の順（B → A）で close される。close は catch ブロックより前に実行されるので、例外が発生した場合も「body → close（逆順）→ catch」の順になる。","topic":"例外処理","mono":1},{"id":"exl-011","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class OutOfStockException extends Exception {\n    OutOfStockException(String msg) { super(msg); }\n}\npublic class Main {\n    static void order(int n) throws OutOfStockException {\n        if (n > 3) throw new OutOfStockException(\"在庫不足\");\n    }\n    public static void main(String[] args) {\n        try {\n            order(5);\n        } catch (OutOfStockException e) {\n            System.out.println(e.getMessage());\n        }\n    }\n}","choices":["在庫不足","OutOfStockException","OutOfStockException: 在庫不足","コンパイルエラー"],"answer":[0],"explain":"独自例外は Exception（検査例外にしたい場合）や RuntimeException（非検査例外にしたい場合）を継承して作る。コンストラクタで super(message) に渡したメッセージは getMessage() で取り出せる。ここでは検査例外なので、throws 宣言と catch がそろっていることもポイント。","topic":"例外処理","mono":1},{"id":"exl-012","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"double d = 10.0 / 0;\nSystem.out.println(d);\nint i = 10 / 0;\nSystem.out.println(i);","choices":["Infinity と表示された後、ArithmeticException がスローされる","NaN と表示された後、ArithmeticException がスローされる","最初の行で ArithmeticException がスローされ、何も表示されない","Infinity と 0 が表示される","コンパイルエラー"],"answer":[0],"explain":"浮動小数点数の 0 除算は例外にならず、Infinity（または NaN）になる。整数（int・long）を 0 で / または % したときだけが ArithmeticException（/ by zero）をスローする。","topic":"例外処理"},{"id":"exl-013","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String s = \"3.0\";\nint n = Integer.parseInt(s);\nSystem.out.println(n);","choices":["3 と表示される","3.0 と表示される","実行時に NumberFormatException がスローされる","コンパイルエラー"],"answer":[2],"explain":"Integer.parseInt は、引数が整数として解釈できない文字列だと NumberFormatException（非検査例外）をスローする。\"3.0\" は小数点を含むので整数にならない。前後の空白を含む \" 3\" なども同様に例外になる。","topic":"例外処理"},{"id":"exl-014","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int[] a = {1, 2, 3};\nfor (int i = 0; i <= a.length; i++) {\n    System.out.print(a[i] + \" \");\n}","choices":["1 2 3 と表示される","1 2 3 と表示された後、ArrayIndexOutOfBoundsException がスローされる","1 2 3 0 と表示される","コンパイルエラー"],"answer":[1],"explain":"配列の添字は 0 〜 length - 1。ループ条件が i <= a.length なので、最後に a[3] にアクセスして ArrayIndexOutOfBoundsException が発生する。それまでの 1 2 3 は表示済み。添字のチェックは実行時に行われるので、コンパイルは通る。","topic":"例外処理"},{"id":"exl-015","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"Integer count = null;\nint n = count;\nSystem.out.println(n);","choices":["0 と表示される","null と表示される","実行時に NullPointerException がスローされる","2行目でコンパイルエラー"],"answer":[2],"explain":"ラッパークラスの変数に null が入っている状態で基本データ型に代入すると、アンボクシング（内部的に intValue() の呼び出し）が行われ NullPointerException になる。型としては Integer → int の代入は正しいので、コンパイルは通る。","topic":"ラムダとAPI","sub":"API"},{"id":"exl-016","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.function.Predicate;\n\npublic class Main {\n    public static void main(String[] args) {\n        Predicate<String> p = s -> s.isEmpty();\n        System.out.println(p.test(\"\") + \" \" + p.negate().test(\"\"));\n    }\n}","choices":["true false","false true","true true","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"Predicate<T> は boolean test(T t) を持つ関数型インターフェース。negate() は結果を反転した Predicate を返す。p.test(\"\") は空文字なので true、p.negate().test(\"\") は false。","topic":"ラムダとAPI","mono":1,"sub":"ラムダ"},{"id":"exl-017","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.function.Function;\n\npublic class Main {\n    public static void main(String[] args) {\n        Function<Integer, Integer> f = x -> x + 1;\n        Function<Integer, Integer> g = x -> x * 2;\n        System.out.println(f.andThen(g).apply(3) + \" \" + f.compose(g).apply(3));\n    }\n}","choices":["8 7","7 8","8 8","7 7","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"Function<T, R> は R apply(T t) を持つ。f.andThen(g) は「f の後に g」なので (3 + 1) * 2 = 8。f.compose(g) は「g の後に f」なので 3 * 2 + 1 = 7。","topic":"ラムダとAPI","mono":1,"sub":"ラムダ"},{"id":"exl-018","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.function.Consumer;\nimport java.util.function.Supplier;\n\npublic class Main {\n    public static void main(String[] args) {\n        Supplier<String> s = () -> \"Java\";\n        Consumer<String> c = x -> System.out.println(x + \"!\");\n        c.accept(s.get());\n    }\n}","choices":["Java!","Java","!Java","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"Supplier<T> は引数なしで値を返す T get()、Consumer<T> は引数を受け取って何も返さない void accept(T t) を持つ。s.get() で \"Java\" を取り出し、c.accept で \"!\" を付けて表示する。","topic":"ラムダとAPI","mono":1,"sub":"ラムダ"},{"id":"exl-019","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int n = 1;\nRunnable r = () -> System.out.println(n);\nn++;\nr.run();","choices":["1 と表示される","2 と表示される","2行目でコンパイルエラー","3行目でコンパイルエラー"],"answer":[2],"explain":"ラムダ式の中から参照できるローカル変数は、final か実質的に final（宣言後に値が変わらない）なものに限られる。3行目で n++ しているため n は実質的 final ではなくなり、ラムダ式内で n を参照している2行目がコンパイルエラーになる。","topic":"ラムダとAPI","sub":"ラムダ"},{"id":"exl-020","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["java.util.function.Function<Integer, Integer> f = x -> x * 2;","java.util.function.Function<Integer, Integer> f = (x) -> { x * 2 };","java.util.function.Function<Integer, Integer> f = (Integer x) -> { return x * 2; };","java.util.function.Function<Integer, Integer> f = x -> return x * 2;","java.util.function.BiFunction<Integer, Integer, Integer> f = (var x, y) -> x + y;","java.util.function.Supplier<String> s = () -> \"a\";"],"answer":[1,3,4],"explain":"値を返すラムダで { } を使うなら、中身は文なので return とセミコロンが必要（void のラムダなら return は不要）。{ } を省略するなら return も書けない。引数の型は「全部書く」「全部省略」「全部 var」のどれかにそろえる必要があり、var と省略の混在はエラー。引数が0個なら () は省略できない。","topic":"ラムダとAPI","mono":1,"sub":"ラムダ"},{"id":"exl-021","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String s = \"abc\";\njava.util.function.Predicate<String> p = s -> s.isEmpty();\nSystem.out.println(p.test(s));","choices":["true と表示される","false と表示される","2行目でコンパイルエラー","実行時に例外がスローされる"],"answer":[2],"explain":"ラムダ式の引数名は、同じスコープにあるローカル変数と同じ名前にできない（ラムダ式は新しいスコープを作らない）。s はすでにローカル変数として宣言されているので、引数名 s はコンパイルエラーになる。","topic":"ラムダとAPI","sub":"ラムダ"},{"id":"exl-022","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"System.out.println(Math.round(-2.5) + \" \" + Math.ceil(-1.2) + \" \" + Math.max(3, 2.0));","choices":["-2 -1.0 3.0","-3 -2.0 3","-2 -1.0 3","-3 -1.0 3.0","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"Math.round は「0.5 を足してから、小さい方（負の無限大方向）へ切り捨てる」＝ Math.floor(x + 0.5) なので、-2.5 → -2.0 → -2（long 型）。0 の方向への切り捨て（(long) キャスト）とは違い、Math.round(-2.6) は -3 になる。Math.ceil は正の無限大方向への切り上げで -1.2 → -1.0（double 型）。Math.max(3, 2.0) は int が double に拡大されるので 3.0。","topic":"ラムダとAPI","mono":1,"sub":"API"},{"id":"exl-023","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"Integer a = 1000;\nInteger b = 1000;\nLong l = 1000L;\nSystem.out.println(a.equals(b) + \" \" + a.equals(l));","choices":["true true","true false","false false","false true","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[1],"explain":"ラッパークラスの値の比較は == ではなく equals を使う。ただし equals は型も比べるので、Integer と Long は値が同じでも false になる。a.equals(l) の l は Long 型のまま渡されるため不一致。","topic":"ラムダとAPI","mono":1,"sub":"API"},{"id":"exl-024","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["Long x = 10;","long y = 10; Long x = y;","Integer i = 10; long l = i;","Double d = 1;","Character c = 'a'; int n = c;"],"answer":[0,3],"explain":"オートボクシングは原則「同じ種類の基本データ型 → そのラッパー」だけ。int の 10 を Long や Double に直接ボクシングすることはできない（10L や 1.0 と書く必要がある）。ただし範囲内の int 定数は Byte・Short・Character には代入できる（Byte b = 10; は通る）。逆のアンボクシングは、取り出した後に拡大変換してよい（Integer → int → long、Character → char → int）。","topic":"ラムダとAPI","mono":1,"sub":"API"},{"id":"exl-025","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"System.out.println(Integer.parseInt(\"10\") + Integer.parseInt(\"20\") + \"3\");","choices":["303","33","60","1023","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"Integer.parseInt は文字列を int に変換する。式は左から評価されるので、まず 10 + 20 = 30（int 同士の加算）、次に 30 + \"3\" で文字列連結になり \"303\"。","topic":"ラムダとAPI","mono":1,"sub":"API"},{"id":"exl-026","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"java.util.List<Integer> ints = new java.util.ArrayList<>();\njava.util.List<Number> nums = ints;\nnums.add(1);\nSystem.out.println(nums);","choices":["[1] と表示される","2行目でコンパイルエラー","3行目でコンパイルエラー","実行時に ClassCastException がスローされる"],"answer":[1],"explain":"型引数どうしの継承関係は、ジェネリック型には引き継がれない。Integer は Number のサブクラスだが、List<Integer> は List<Number> のサブタイプではない（ArrayList<Integer> を List<Integer> に代入できるのとは別の話）。許すと nums 経由で Double なども add できてしまうため、代入の時点（2行目）でコンパイルエラーになる。","topic":"ラムダとAPI","sub":"ジェネリクス"},{"id":"exl-027","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Box<T> {\n    private final T value;\n    Box(T value) { this.value = value; }\n    T get() { return value; }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Box<String> s = new Box<>(\"hello\");\n        Box<Integer> n = new Box<>(5);\n        System.out.println(s.get().toUpperCase() + \" \" + n.get());\n    }\n}","choices":["HELLO 5","hello 5","HELLO 5.0","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"型パラメータ T は、インスタンス化の時に指定した型に置き換わる。Box<String> の get() は String を返すのでキャスト無しで toUpperCase() を呼べる。new Box<>(5) はダイヤモンド演算子で型引数を推論し、5 はオートボクシングで Integer になる。","topic":"ラムダとAPI","mono":1,"sub":"ジェネリクス"},{"id":"exl-028","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.ArrayList;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Double> list = new ArrayList<>();\n        list.add(Math.sqrt(9));\n        System.out.println(list);\n    }\n}","choices":["[3.0] と表示される","5行目でコンパイルエラー","6行目でコンパイルエラー","実行時に例外がスローされる"],"answer":[1],"explain":"java.lang パッケージ（String・Math・Integer・System など）と、自分と同じパッケージのクラスは import なしで使えるが、java.util などほかのパッケージのクラスは import 文か完全修飾名が必要。ArrayList は1行目で import しているので使えるが、List は import していないので5行目で cannot find symbol のコンパイルエラーになる。import java.util.List;（または import java.util.*;）を足すか、java.util.List と完全修飾名で書けば通る。","topic":"パッケージとモジュール","sub":"パッケージ"},{"id":"exl-029","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import static java.lang.Math.PI;\n\npublic class Main {\n    public static void main(String[] args) {\n        double r = PI;\n        System.out.println(Math.floor(r * 100) / 100);\n    }\n}","choices":["3.14","3.141592653589793","3.0","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"static インポートを使うと、クラス名を付けずに static メンバを使える。import static java.lang.Math.PI; により PI とだけ書ける。java.lang は自動インポートされるが、static メンバを名前だけで使うには static インポートが別途必要。","topic":"パッケージとモジュール","mono":1,"sub":"パッケージ"},{"id":"exl-030","type":"single","q":"モジュール宣言（module-info.java）で、自分のモジュールのパッケージを、他のモジュールのコードからコンパイル時にも実行時にも使えるように公開するディレクティブは？","choices":["exports","requires","opens","uses"],"answer":[0],"explain":"exports <パッケージ名> で、そのパッケージの public な型を他のモジュールに公開する。opens はパッケージを実行時のリフレクション用に開くだけで、他のモジュールのコードからコンパイル時に型を使えるようにはならない。requires は自分が使う他のモジュールの宣言、uses は ServiceLoader で利用するサービスの宣言。","topic":"パッケージとモジュール","sub":"モジュール"},{"id":"exl-031","type":"single","q":"モジュールについて正しい説明はどれか。","choices":["どのモジュールも、module-info.java に requires を書かなくても java.base モジュールに暗黙に依存している","モジュール内の public クラスは、exports の指定が無くても他のモジュールから使える","1つのモジュールは1つのパッケージしか含められない","module-info.java はどのパッケージのディレクトリに置いてもよい"],"answer":[0],"explain":"すべてのモジュールは java.base（java.lang や java.util を含む）を暗黙に requires している。public な型でも、そのパッケージが exports されていなければ他のモジュールからは使えない。module-info.java はモジュールのルート（パッケージのディレクトリの外）に置く。","topic":"パッケージとモジュール","sub":"モジュール"},{"id":"prog-001","type":"multi","q":"main メソッドの宣言として、コンパイルが通るものを【すべて】選べ（java コマンドで起動できるかどうかは問わない）。","choices":["class A { static public void main(final String[] a) { } }","class A { public static void main(String... args) { } }","class A { public void static main(String[] args) { } }","class A { public static int main(String[] args) { return 0; } }","class A { public void main(String[] args) { } }","class A { public static void main(String args...) { } }"],"answer":[0,1,3,4],"explain":"public と static の順番は自由で、引数は String[] でも String...（可変長引数）でもよく、引数に final を付けても、引数名を a にしてもよい。戻り値の型はメソッド名の直前に書くので public void static はエラー、可変長引数の ... は型の直後に書くので String args... もエラー。int を返す main や static の無い main も、普通のメソッドとしてはコンパイルが通るが、Java 17 ではエントリーポイントとして認められず、java コマンドで起動するとエラーになる。","topic":"Javaプログラムの基本","mono":1,"sub":"プログラムの基本"},{"id":"prog-002","type":"single","q":"Java 17 で、クラス Main に次のいずれか1つの main メソッドだけを書き（本体は正しく書かれており、コンパイルは通る）、java Main で起動した。main メソッドが正常に呼び出されるものはどれか。","choices":["public static void main(String... args)","public void main(String[] args)","static void main(String[] args)","public static int main(String[] args)"],"answer":[0],"explain":"java コマンドが最初に呼び出すエントリーポイントは public static void main(String[] args) の形だけで、引数は String args[] や可変長の String... と書いてもよく、引数名も自由。static が無い、public が無い、戻り値が void でない、のどれかに当てはまると、コンパイルは通っても起動時に「Main method is not static」「Main method not found」などのエラーになる。","topic":"Javaプログラムの基本","sub":"プログラムの基本"},{"id":"prog-003","type":"single","q":"次のコードを java Main \"Hello World\" Java で起動するとどうなる？","code":"public class Main {\n    public static void main(String[] args) {\n        System.out.println(args.length + \":\" + args[0]);\n    }\n}","choices":["2:Hello World","3:Hello","3:\"Hello","2:\"Hello World\"","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"コマンドライン引数は空白で区切られるが、\"Hello World\" のように二重引用符で囲むと、空白を含めて1つの引数になる。引用符そのものは値に含まれない。args は {\"Hello World\", \"Java\"} の2要素なので、2:Hello World と表示される。","topic":"Javaプログラムの基本","mono":1,"sub":"プログラムの基本"},{"id":"prog-004","type":"single","q":"次のコードを java Main 10 20 で起動するとどうなる？","code":"public class Main {\n    public static void main(String[] args) {\n        System.out.println(args[0] + args[1] + \" \" + args.length);\n    }\n}","choices":["1020 2","30 2","Main10 3","30 3","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"args に入るのはクラス名（Main）の後ろに書いた値だけなので、args[0] は \"10\"、args.length は 2 になる。コマンドライン引数は数字に見えても String なので、args[0] + args[1] は足し算ではなく文字列の連結で \"1020\"。数値として計算したいときは Integer.parseInt(args[0]) のように変換する。","topic":"Javaプログラムの基本","mono":1,"sub":"プログラムの基本"},{"id":"prog-005","type":"single","q":"次のコードを java Main で（引数を付けずに）起動するとどうなる？","code":"public class Main {\n    public static void main(String[] args) {\n        System.out.println(args.length);\n        System.out.println(args[0]);\n    }\n}","choices":["0 と表示された後、ArrayIndexOutOfBoundsException が発生する","何も表示されずに NullPointerException が発生する","0 と null が表示される","0 と表示された後、空の行が表示される","コンパイルエラー"],"answer":[0],"explain":"引数なしで起動しても args は null にはならず、要素数0の配列が渡される。そのため args.length は 0 と表示され、次の args[0] は存在しない要素へのアクセスとなって ArrayIndexOutOfBoundsException が発生する。引数を使う前に args.length で個数を確かめるのが定石。","topic":"Javaプログラムの基本","sub":"プログラムの基本"},{"id":"prog-006","type":"single","q":"次のコードを java Main で（引数を付けずに）起動するとどうなる？","code":"public class Main {\n    public static void main(int n) {\n        System.out.println(\"int \" + n);\n    }\n    public static void main(String[] args) {\n        System.out.println(\"String[] \" + args.length);\n        main(args.length + 1);\n    }\n}","choices":["String[] 0\nint 1","String[] 0","コンパイルエラー","起動時にエラーになる"],"answer":[0],"explain":"main も普通の static メソッドなので、引数の型が違う main を並べてオーバーロードできる。java コマンドが起動時に呼び出すのは main(String[]) の方だけで、main(int) はプログラムの中から普通のメソッドとして呼べる。args.length は 0 なので、String[] 0 と表示された後に main(1) が呼ばれて int 1 と表示される。","topic":"Javaプログラムの基本","mono":1,"sub":"プログラムの基本"},{"id":"prog-007","type":"single","q":"カレントディレクトリにある Hello.java（public class Hello が書かれている）をコンパイルし、引数 A を渡して実行したい。コマンドの組み合わせとして正しいものは？","choices":["javac Hello.java → java Hello A","javac Hello.java → java Hello.class A","javac Hello → java Hello A","javac Hello.java A → java Hello"],"answer":[0],"explain":"javac にはソースファイル名を拡張子 .java まで付けて渡し、java には拡張子を付けずにクラス名だけを渡す。java Hello.class と書くと「Hello.class」という名前のクラスを探しに行き、見つからずにエラーになる。コマンドライン引数はコンパイル時ではなく実行時に、java コマンドのクラス名の後ろに並べる。","topic":"Javaプログラムの基本","sub":"プログラムの基本"},{"id":"prog-008","type":"single","q":"Java 17 で、javac を使わずに java Hello.java X のようにソースファイルを直接指定して実行した（Hello.java の最初のクラスに main メソッドがある）。正しい説明はどれか。","choices":["ソースファイルがメモリ上でコンパイルされてから実行され、Hello.class ファイルは作られない","先に javac Hello.java を実行しておかないとエラーになる","Hello.class ファイルがカレントディレクトリに作られ、次回からはそれが使われる","ファイル名の後ろに書いた X は、main メソッドの args には渡されない"],"answer":[0],"explain":"Java 11 以降は、java コマンドに .java ファイルを直接渡すと、メモリ上でコンパイルしてそのまま実行できる（ソースファイルモード）。.class ファイルはディスクに書き出されない。ファイル名の後ろの値は通常どおり args に渡され、ファイル内に複数のクラスがある場合は、最初に宣言されたトップレベルクラスの main が実行される。","topic":"Javaプログラムの基本","sub":"プログラムの基本"},{"id":"prog-009","type":"single","q":"次のコード（Main.java）をコンパイル・実行するとどうなる？","code":"import java.util.ArrayList;\npackage shop;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(new ArrayList<String>());\n    }\n}","choices":["[] と表示される","2行目でコンパイルエラー","6行目でコンパイルエラー","実行時に例外が発生する"],"answer":[1],"explain":"ソースファイルの中は「package 文 → import 文 → クラスなどの型宣言」の順に書く決まりがある。package 文より前に置けるのはコメントと空白だけなので、import の後ろにある2行目の package 文がコンパイルエラーになる。package 文は1ファイルに1つまで、import 文はいくつ書いてもよい。","topic":"Javaプログラムの基本","sub":"プログラムの基本"},{"id":"prog-010","type":"single","q":"次のコードを Main.java という名前で保存し、コンパイル・実行するとどうなる？","code":"public class Main {\n    public static void main(String[] args) {\n        System.out.println(new Helper().name());\n    }\n}\npublic class Helper {\n    String name() { return \"helper\"; }\n}","choices":["helper と表示される","1行目でコンパイルエラー","6行目でコンパイルエラー","実行時に例外が発生する"],"answer":[2],"explain":"public なトップレベルクラスは、クラス名と同じ名前のファイル（クラス名.java）に書かなければならない。そのため1つのファイルに書ける public なトップレベルクラスは1つまでで、Main.java の中にある public class Helper（6行目）がコンパイルエラーになる。Helper の public を外せば同じファイルのまま使える（public でないクラスは1ファイルに何個書いてもよい）。","topic":"Javaプログラムの基本","sub":"プログラムの基本"},{"id":"prog-011","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    public static void main(String[] args) {\n        /* 一時的に無効化\n        /* 旧コード */\n        System.out.print(\"A\");\n        */\n        System.out.print(\"B\");\n    }\n}","choices":["B と表示される","AB と表示される","4行目でコンパイルエラー","6行目でコンパイルエラー"],"answer":[3],"explain":"/* */ のコメントは入れ子にできない。3行目の /* で始まったコメントは、4行目に出てくる最初の */ で終わる（途中の /* はコメントの中の文字として無視される）。そのため5行目の print(\"A\") は普通のコードに戻り、6行目に残った */ が文法エラーになる。","topic":"Javaプログラムの基本","sub":"プログラムの基本"},{"id":"prog-012","type":"single","q":"変数宣言として、コンパイルエラーになるものはどれか。","choices":["int __ = 1;","int $$ = 1;","int _ = 1;","int _$ = 1;"],"answer":[2],"explain":"識別子には文字・数字・_・$ を使え、先頭が数字でなければ _ や $ で始めてもよい。ただしアンダースコア1文字だけの _ は Java 9 以降キーワード扱いになり、識別子としては使えない。__（2文字）や _$ のように組み合わせれば使える。","topic":"Javaプログラムの基本","mono":1,"sub":"識別子"},{"id":"prog-013","type":"multi","q":"変数宣言として、コンパイルが通るものを【すべて】選べ。","choices":["int $price = 100;","int 2nd = 2;","int const = 3;","int var = 4;","int record = 5, sealed = 6, permits = 7;","int null = 0;"],"answer":[0,3,4],"explain":"識別子は数字で始められない（2nd は不可）。const は goto と同じく「予約されているが使われていないキーワード」、null は true・false と同じくリテラルなので、どちらも識別子にできない。var・record・sealed・permits は特定の場所でだけ意味を持つ文脈キーワードなので変数名には使える（ただし、クラス名などの型の名前には使えない）。$ は先頭にも途中にも使える。","topic":"Javaプログラムの基本","mono":1,"sub":"識別子"},{"id":"prog-014","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int $price = 100;\nint _tax = 10;\nint record = 2;\nint yield = 3;\nint goto = 4;\nSystem.out.println($price + _tax + record + yield);","choices":["115 と表示される","3行目でコンパイルエラー","4行目でコンパイルエラー","5行目でコンパイルエラー"],"answer":[3],"explain":"goto は const と同じく、Java では使われていないが予約されているキーワードなので、変数名にできず5行目がエラーになる。record や yield は後から追加された文脈キーワードで、変数名（ローカル変数やフィールド）には使える（型の名前には使えない）。$ や _ で始まる名前も有効なので、5行目が無ければ 115 と表示される。","topic":"Javaプログラムの基本","sub":"識別子"},{"id":"prog-015","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static int total = 10;\n    static int total() {\n        return 20;\n    }\n    public static void main(String[] args) {\n        int total = 1;\n        System.out.println(total + total() + Main.total);\n    }\n}","choices":["31","40","22","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"変数とメソッドは名前の管理が別々なので、同じ名前 total のフィールドとメソッドを同時に宣言できる（() が付けばメソッドの呼び出し）。main の中ではローカル変数 total がフィールドを隠す（シャドウイング）ので total は 1。隠れたフィールドは Main.total と書けば参照できるので、1 + 20 + 10 = 31。","topic":"Javaプログラムの基本","mono":1,"sub":"識別子"},{"id":"prog-016","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class var {\n    int value = 1;\n}\npublic class Main {\n    public static void main(String[] args) {\n        int var = 2;\n        System.out.println(var);\n    }\n}","choices":["2 と表示される","1行目でコンパイルエラー","6行目でコンパイルエラー","1行目と6行目の両方でコンパイルエラー"],"answer":[1],"explain":"var は予約語ではなく文脈キーワードなので、6行目のようにローカル変数の名前には使える。一方、Java 10 以降 var は型の名前（クラス名・インターフェース名など）には使えないので、1行目がコンパイルエラーになる。record・sealed・permits・yield も同様に、変数名にはできるが型の名前にはできない。","topic":"Javaプログラムの基本","sub":"識別子"},{"id":"prog-017","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static int a;\n    static Integer b;\n    static char c;\n    static float f;\n    public static void main(String[] args) {\n        System.out.println(a + \" \" + b + \" \" + (int) c + \" \" + f);\n    }\n}","choices":["0 null 0 0.0","0 0 0 0.0","0 null 32 0.0","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"フィールド（static 変数・インスタンス変数）は、初期化しなくても型ごとの既定値が入る。int は 0、float は 0.0、char は '\\u0000'（文字コード 0 で、空白の 32 ではない）、Integer のような参照型はラッパークラスでも null。既定値が入るのはフィールドと配列の要素だけで、ローカル変数には入らない。","topic":"コンストラクタと初期化","mono":1,"sub":"初期化"},{"id":"prog-018","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static int count = 5;\n    public static void main(String[] args) {\n        int count;\n        System.out.println(count);\n    }\n}","choices":["5 と表示される","0 と表示される","4行目でコンパイルエラー","5行目でコンパイルエラー"],"answer":[3],"explain":"フィールドと同じ名前のローカル変数は宣言してよく、4行目以降の count はローカル変数の方を指す（フィールドは隠れる）。ローカル変数には既定値が無いので、代入する前に読むと variable count might not have been initialized のコンパイルエラーになる。エラーになるのは宣言した4行目ではなく、値を読んでいる5行目。","topic":"コンストラクタと初期化","sub":"初期化"},{"id":"prog-019","type":"multi","q":"main メソッドの中に書いたとき、コンパイルが通るものを【すべて】選べ。","choices":["int x;\nif (args.length > 0) {\n    x = 1;\n} else {\n    x = 2;\n}\nSystem.out.println(x);","int x;\nx++;","String s;\nSystem.out.println(s == null);","int x;\nfor (int i = 0; i < 3; i++) {\n    x = i;\n}\nSystem.out.println(x);","final int x;\nx = 10;\nSystem.out.println(x);","int x;\nint y = 5;\nSystem.out.println(y);"],"answer":[0,4,5],"explain":"ローカル変数は、どの経路を通っても代入が済んでいる状態でなければ読めない（x++ も s == null も「読む」に当たり、参照型だからといって null が入っているわけではない）。if と else の両方で代入していれば通るが、i < 3 のような条件の for 文の中の代入は、コンパイラが条件の値を追わないため「一度も回らないかもしれない」とみなされ、ループの後で読むとエラーになる（for (;;) のような条件の無いループを break で抜ける場合は、代入済みとみなされる）。final のローカル変数は宣言とは別に1回だけ代入してよく、宣言しただけで読まない変数はエラーにならない。","topic":"コンストラクタと初期化","mono":1,"sub":"初期化"},{"id":"prog-020","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static { System.out.print(\"S\"); }\n    { System.out.print(\"I\"); }\n    Main() { System.out.print(\"C\"); }\n    public static void main(String[] args) {\n        System.out.print(\"M\");\n        new Main();\n        new Main();\n    }\n}","choices":["SMICIC","MSICIC","SMICSIC","SMCICI","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"static 初期化子（static { }）は、クラスが初めて使われるときに1回だけ実行される。Main クラスは main メソッドを呼ぶ前に初期化されるので、S は M より先に出る。インスタンス初期化子（{ }）は new のたびにコンストラクタ本体より先に実行されるので、new するごとに I → C の順になる。","topic":"コンストラクタと初期化","mono":1,"sub":"初期化"},{"id":"prog-021","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class A {\n    static { System.out.print(\"1\"); }\n    { System.out.print(\"2\"); }\n    A() { System.out.print(\"3\"); }\n}\nclass B extends A {\n    static { System.out.print(\"4\"); }\n    { System.out.print(\"5\"); }\n    B() { System.out.print(\"6\"); }\n}\npublic class Main {\n    public static void main(String[] args) {\n        new B();\n        System.out.print(\" \");\n        new B();\n    }\n}","choices":["142356 2356","123456 123456","142536 2536","142356 142356","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"最初の new B() では、まずクラスの初期化として親 A → 子 B の順に static 初期化子が実行される（14）。続くインスタンスの生成では、親の部分（A のインスタンス初期化子 → A のコンストラクタ、23）が済んでから、子の部分（B のインスタンス初期化子 → B のコンストラクタ、56）が実行される。static 初期化子はクラスごとに1回だけなので、2回目の new B() では 2356 だけが出る。","topic":"コンストラクタと初期化","mono":1,"sub":"初期化"},{"id":"prog-022","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static int x = 10;\n    static { x += 5; }\n    static int y = x * 2;\n    static { x = 1; }\n    public static void main(String[] args) {\n        System.out.println(x + \" \" + y);\n    }\n}","choices":["1 30","1 20","10 20","1 2","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"static 変数の初期化式と static 初期化子は、区別なく書かれている順に上から1つずつ実行される。x = 10 → x += 5 で 15 → y = x * 2 で 30 → x = 1 の順なので、y は 30、x は最後に 1 になる。y は計算された時点の値のまま残り、後で x が変わっても連動しない。","topic":"コンストラクタと初期化","mono":1,"sub":"初期化"},{"id":"prog-023","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Box {\n    int v = 1;\n    { v *= 10; }\n    Box() { v += 5; }\n    { v *= 2; }\n}\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(new Box().v);\n    }\n}","choices":["25","30","120","15","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"インスタンス変数の初期化式とインスタンス初期化子（{ }）は書かれている順に実行され、それがすべて終わってからコンストラクタの本体が実行される。コンストラクタが初期化子の間に書かれていても、この順番は変わらない。1 → ×10 で 10 → ×2 で 20 → コンストラクタで +5 して 25。","topic":"コンストラクタと初期化","mono":1,"sub":"初期化"},{"id":"prog-024","type":"multi","q":"final フィールドの扱いとして、コンパイルエラーになるものを【すべて】選べ。","choices":["class A {\n    final int x;\n    A() { x = 1; }\n}","class A {\n    final int x;\n    { x = 1; }\n    A() { }\n}","class A {\n    final int x;\n    A() { }\n    A(int n) { x = n; }\n}","class A {\n    static final int X;\n    static { X = 1; }\n}","class A {\n    static final int X;\n    A() { X = 1; }\n}","class A {\n    final int x = 1;\n    A() { x = 2; }\n}"],"answer":[2,4,5],"explain":"宣言時に値を入れない final フィールド（ブランク final）は、インスタンス変数ならインスタンス初期化子の中か、コンストラクタの中で（this(...) で別のコンストラクタを呼ぶものを除いた、すべてのコンストラクタで）、static 変数なら static 初期化子の中で、ちょうど1回代入しなければならない。A(int) でしか代入しないと、A() で生成したときに未初期化になるのでエラー（A() { this(0); } のように A(int) を呼ぶ形にすれば通る）。static final をコンストラクタで代入するのも、宣言時に初期化済みの final へ再代入するのもエラー。","topic":"コンストラクタと初期化","mono":1,"sub":"初期化"},{"id":"prog-025","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    int a = b + 1;\n    int b = 2;\n    public static void main(String[] args) {\n        System.out.println(new Main().a);\n    }\n}","choices":["3 と表示される","1 と表示される","2行目でコンパイルエラー","5行目でコンパイルエラー"],"answer":[2],"explain":"フィールドの初期化式は上から順に実行されるので、後ろで宣言されるフィールドを初期化式の中で名前だけで読むと illegal forward reference（不正な前方参照）のコンパイルエラーになる。2行目と3行目を入れ替えれば 3 と表示される。なお this.b と書くとコンパイルは通るが、その時点の b は既定値の 0 なので a は 1 になる。","topic":"コンストラクタと初期化","sub":"初期化"},{"id":"prog-026","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Helper {\n    static { System.out.print(\"H\"); }\n    static void run() { System.out.print(\"R\"); }\n}\npublic class Main {\n    public static void main(String[] args) {\n        System.out.print(\"M\");\n        Helper h = null;\n        System.out.print(\"N\");\n        Helper.run();\n        Helper.run();\n    }\n}","choices":["MNHRR","HMNRR","MHNRR","MNHRHR","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"static 初期化子は、プログラムの開始時にまとめて動くのではなく、そのクラスが初めて実際に使われたとき（static メソッドの呼び出しや new など）に1回だけ実行される。Helper 型の変数を宣言して null を入れただけでは、クラスの初期化は起きない。最初の Helper.run() の直前に H が出て、2回目の呼び出しでは static 初期化子は動かない。","topic":"コンストラクタと初期化","mono":1,"sub":"初期化"},{"id":"api-001","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String s = \"karaoke\";\nint a = s.indexOf(\"ra\");\nint b = s.lastIndexOf('a');\nint c = s.indexOf('k', 1);\nint d = s.indexOf(\"K\");\nSystem.out.println(a + \" \" + b + \" \" + c + \" \" + d + \" \" + s.charAt(c + 1));","choices":["2 3 5 -1 e","3 4 6 0 e","2 3 0 -1 a","2 3 5 0 e","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"indexOf は先頭から、lastIndexOf は末尾から探し、見つかった位置を0始まりの添字で返す。indexOf('k', 1) は添字1以降だけを探すので、2つ目の k の 5 になる。見つからないときは -1 を返し、大文字と小文字は区別される。charAt(5 + 1) は添字6の 'e'。","topic":"文字列","mono":1},{"id":"api-002","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String s = \"Silver\";\nSystem.out.println(s.substring(1, 3) + \"[\" + s.substring(6) + \"]\");\nSystem.out.println(s.substring(4, 7));","choices":["il[] と表示された後、StringIndexOutOfBoundsException がスローされる","ilv[] と表示された後、StringIndexOutOfBoundsException がスローされる","il[] と er が表示される","何も表示されずに StringIndexOutOfBoundsException がスローされる","コンパイルエラー"],"answer":[0],"explain":"substring(begin, end) は begin から end の1つ手前までを返す（end の位置の文字は含まない）ので、substring(1, 3) は \"il\"。begin が文字列の長さと同じ substring(6) は例外にならず、空文字を返す。end が長さ（6）を超える substring(4, 7) は StringIndexOutOfBoundsException になる。","topic":"文字列"},{"id":"api-003","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String s = \"a--b---c\";\nString t = s.replace(\"--\", \"-\");\nString u = s.replace('-', '+');\nSystem.out.println(t + \" \" + u + \" \" + s);","choices":["a-b--c a++b+++c a--b---c","a-b-c a++b+++c a--b---c","a-b--c a+-b---c a--b---c","a-b--c a++b+++c a-b--c","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"replace は一致した部分を【すべて】置き換えた新しい文字列を返す。文字列版は先頭から順に探して置き換え、置き換えた結果をもう一度探し直すことはないので、\"---\" は先頭の \"--\" だけが \"-\" になって \"--\" が残る。char 版は '-' を1つ残らず '+' に替える。元の s は変わらない。","topic":"文字列","mono":1},{"id":"api-004","type":"single","q":"次のコードをコンパイル・実行するとどうなる？（\\u3000 は全角スペース）","code":"String a = \" \";\nString b = \"\\u3000\";\nSystem.out.println(a.isEmpty() + \" \" + a.isBlank() + \" \" + b.trim().isEmpty() + \" \" + b.strip().isEmpty());","choices":["false true false true","true true true true","false true true true","false false false true","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"isEmpty は長さが0のときだけ true、isBlank は空白文字しか無いとき（空文字も含む）に true。trim が取り除くのは文字コードが U+0020 以下の文字（半角スペース・タブ・改行など）だけなので、全角スペースは残る。strip は Character.isWhitespace で空白かどうかを判定するため、全角スペースも取り除く。","topic":"文字列","mono":1},{"id":"api-005","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String a = String.join(\"-\", \"2024\", \"09\", \"27\");\nString b = String.join(\"-\", \"solo\");\nString c = \"ab\".repeat(2) + \"cd\".repeat(0);\nSystem.out.println(a + \" \" + b + \" \" + c);","choices":["2024-09-27 solo abab","2024-09-27- solo- abab","2024-09-27 solo ababab","2024-09-27 solo ababcd","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"String.join(区切り文字, 要素...) は要素と要素の【間】にだけ区切り文字を入れるので、要素が1つなら区切り文字は付かない。repeat(n) は n 回つなげた文字列を返し、repeat(0) は空文字になる（負の数を渡すと IllegalArgumentException）。","topic":"文字列","mono":1},{"id":"api-006","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String s = null;\nObject o = null;\nSystem.out.println(\"A\" + s + String.valueOf(o));\nSystem.out.println(\"B\".concat(s));","choices":["Anullnull と表示された後、NullPointerException がスローされる","A と B が表示される","Anullnull と Bnull が表示される","何も表示されずに NullPointerException がスローされる","コンパイルエラー"],"answer":[0],"explain":"+ 演算子による連結と String.valueOf(Object) は、null を \"null\" という文字列として扱う。一方、concat は引数が null だと NullPointerException をスローする。そのため1つ目の println は正常に表示され、2つ目で例外になる。","topic":"文字列"},{"id":"api-007","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String a = \"java\";\nString b = \"JAVA\";\nString c = \"javascript\";\nSystem.out.println(a.equals(b) + \" \" + a.equalsIgnoreCase(b) + \" \" + (a.compareTo(b) < 0) + \" \" + (a.compareTo(c) < 0));","choices":["false true false true","false true true true","false true false false","true true false true","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"compareTo は先頭から1文字ずつ文字コードを比べ、最初に違った文字の差を返す（負なら辞書順で前）。大文字（A〜Z は 65〜90）は小文字（a〜z は 97〜122）より前なので、\"java\".compareTo(\"JAVA\") は正の値になる。片方がもう片方の先頭部分と一致するときは短い方が前で、\"java\".compareTo(\"javascript\") は負の値。equalsIgnoreCase は大文字と小文字を区別せずに比べる。","topic":"文字列","mono":1},{"id":"api-008","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String s = \" Java Silver \".trim().toLowerCase().replace(' ', '_').substring(2);\nSystem.out.println(s + \" \" + s.length());","choices":["va_silver 9","ava_silver_ 11","ava_silver 10","Va_Silver 9","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"String のメソッドは元の文字列を書き換えず、結果を String として返す。戻り値も String なので、文字列リテラルからでもメソッドを続けて呼べ、左から順に適用される（変える所が無いときは、trim() などが元のオブジェクトをそのまま返すこともある）。trim で前後の空白が消えて \"Java Silver\"、小文字にして空白を _ に置き換えると \"java_silver\"、substring(2) で先頭2文字を除いた \"va_silver\"（9文字）になる。","topic":"文字列","mono":1},{"id":"api-009","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String file = \"Report_2024.csv\";\nSystem.out.println(file.startsWith(\"report\") + \" \" + file.endsWith(\".csv\") + \" \" + file.contains(\"\") + \" \" + file.startsWith(\"_\", 6));","choices":["false true true true","true true true true","false true false true","false true true false","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"startsWith・endsWith・contains は大文字と小文字を区別するので、\"report\" では一致しない。空文字 \"\" はどの文字列にも含まれるとみなされ、contains(\"\") は true。startsWith(接頭辞, 開始位置) は指定した添字から比べ、添字6は '_' なので true。","topic":"文字列","mono":1},{"id":"api-010","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"StringBuilder a = new StringBuilder(3);\nStringBuilder b = a.append(\"abcdef\").delete(2, 99).insert(0, 'x');\nSystem.out.println(a + \" \" + a.length() + \" \" + (a == b));","choices":["xab 3 true","xab 3 false","x3a 3 true","実行時に StringIndexOutOfBoundsException がスローされる","コンパイルエラー"],"answer":[0],"explain":"new StringBuilder(3) は中身が空で、初期容量が3のオブジェクトを作る（容量は足りなくなれば自動で広がる）。append・delete・insert は自分自身を返すので、a と b は同じオブジェクトを指し、== は true。delete(開始, 終了) は終了が長さを超えていても末尾までとして扱うので、例外にはならない。","topic":"文字列","mono":1},{"id":"api-011","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"StringBuilder sb = new StringBuilder(\"abcdef\");\nsb.replace(1, 4, \"Z\").deleteCharAt(0).reverse();\nSystem.out.println(sb);","choices":["feZ","fZ","fedcbZ","feZZZ","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"StringBuilder の replace(開始, 終了, 文字列) は、開始から終了の1つ手前までの範囲を指定した文字列に置き換える（String の replace とは引数も動きも違う）。\"abcdef\" の添字1〜3 が \"Z\" になって \"aZef\"、deleteCharAt(0) で \"Zef\"、reverse で \"feZ\"。どのメソッドも sb 自身の中身を書き換える。","topic":"文字列","mono":1},{"id":"api-012","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["boolean b = \"abc\".contains('a');","String s = new StringBuilder(\"ab\").reverse();","String s = \"a\" + new StringBuilder(\"b\");","StringBuilder sb = new StringBuilder(\"ab\");\nsb.setCharAt(0, 'x').append(\"y\");","int n = new StringBuilder(\"abc\").indexOf(\"b\");","StringBuilder sb = new StringBuilder(\"a\").append(1).append('b');"],"answer":[0,1,3],"explain":"contains の引数は CharSequence（String など）なので、char は渡せない。reverse の戻り値は StringBuilder なので、String 型の変数に入れるには toString() が要る。setCharAt は戻り値が void なので、続けてメソッドを呼べない。+ 演算子は相手が StringBuilder でも toString() の結果で連結でき、StringBuilder にも indexOf があり、append は int や char も受け取る。","topic":"文字列","mono":1},{"id":"api-013","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"double d = -1.5;\nSystem.out.println(Math.round(d) + \" \" + Math.floor(d) + \" \" + Math.ceil(d) + \" \" + Math.abs(d));","choices":["-1 -2.0 -1.0 1.5","-2 -2.0 -1.0 1.5","-1.0 -2.0 -1.0 1.5","-2 -1.0 -2.0 1.5","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"Math.round は最も近い整数を返し、ちょうど .5 のときは大きい方（正の無限大の方向）に丸めるので、-1.5 は -1 になる。round の戻り値は整数型（引数が double なら long）なので小数点は付かない。floor はその値以下で最大の整数、ceil はその値以上で最小の整数を返すが、戻り値は double なので -2.0 / -1.0 と表示される。abs(double) の戻り値も double。","topic":"ラムダとAPI","mono":1,"sub":"API"},{"id":"api-014","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["int a = Math.abs(-5);","int b = Math.round(1.5);","int c = Math.round(1.5f);","int d = Math.pow(2, 3);","long e = Math.max(1, 2L);","int f = Math.ceil(1.2);"],"answer":[1,3,5],"explain":"Math.round は引数が double なら long、float なら int を返すので、Math.round(1.5) は int 型の変数に代入できない（キャストが必要）。pow・ceil・floor・sqrt は常に double を返す。abs や max は引数の型に合わせたものが選ばれ、max(1, 2L) は long 版になるので long に代入できる。","topic":"ラムダとAPI","mono":1,"sub":"API"},{"id":"api-015","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int a = Integer.MAX_VALUE;\na++;\nlong b = Integer.MAX_VALUE;\nb++;\nlong c = Integer.MAX_VALUE + 1;\nSystem.out.println(a + \" \" + b + \" \" + c);","choices":["-2147483648 2147483648 -2147483648","-2147483648 2147483648 2147483648","2147483648 2147483648 2147483648","-2147483648 -2147483648 -2147483648","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"int の最大値 2147483647 に1を足すとあふれて最小値 -2147483648 になる（例外は発生しない）。b は long 型の変数なので、b++ は long で計算されてあふれない。c の右辺は int 同士の計算なので、先に int であふれてから long に広げられる（Integer.MAX_VALUE + 1L と書けば long で計算される）。","topic":"ラムダとAPI","mono":1,"sub":"API"},{"id":"api-016","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String[] in = {\"+5\", \"010\", \" 7\", \"1_000\"};\nfor (String s : in) {\n    try {\n        System.out.print(Integer.parseInt(s) + \" \");\n    } catch (NumberFormatException e) {\n        System.out.print(\"E \");\n    }\n}","choices":["5 10 E E","5 8 E E","5 10 7 E","E 10 E 1000","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"Integer.parseInt は文字列を10進数として読み、先頭の + や - は受け付ける。先頭に 0 があっても8進数にはならないので \"010\" は 10。前後の空白は取り除かれず、_ で桁を区切れるのはソースコード上の数値リテラルだけなので、\" 7\" と \"1_000\" は NumberFormatException になる。","topic":"ラムダとAPI","mono":1,"sub":"API"},{"id":"api-017","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String pw = \"Ab3_x9\";\nint upper = 0, digit = 0, other = 0;\nfor (char c : pw.toCharArray()) {\n    if (Character.isUpperCase(c)) upper++;\n    else if (Character.isDigit(c)) digit++;\n    else if (!Character.isLetter(c)) other++;\n}\nSystem.out.println(upper + \" \" + digit + \" \" + other);","choices":["1 2 1","1 2 0","1 2 3","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"Character.isUpperCase は大文字、isDigit は数字、isLetter は文字（英字のほか漢字やかなも含む）のときに true を返す。'_' は英字でも数字でもない記号なので、isLetter も isDigit も false になり other に数えられる。else if でつないでいるので、1文字が2か所で数えられることは無い。b や x のような小文字は isUpperCase も isDigit も false で、isLetter が true なので !isLetter も false になり、どこにも数えられない。","topic":"ラムダとAPI","mono":1,"sub":"API"},{"id":"api-018","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        String[] arr = {\"a\", \"b\", \"c\"};\n        List<String> list = Arrays.asList(arr);\n        list.set(0, \"x\");\n        arr[1] = \"y\";\n        System.out.println(list);\n        list.add(\"d\");\n        System.out.println(list);\n    }\n}","choices":["[x, y, c] と表示された後、UnsupportedOperationException がスローされる","[x, b, c] と表示された後、UnsupportedOperationException がスローされる","[x, y, c] と [x, y, c, d] が表示される","7行目で UnsupportedOperationException がスローされる","コンパイルエラー"],"answer":[0],"explain":"Arrays.asList は元の配列をそのまま使う固定長のリストを返す。set で要素を置き換えることはでき、リストへの変更と配列への変更は互いに反映される。要素数が変わる add や remove は UnsupportedOperationException になる。","topic":"配列とリスト","sub":"List"},{"id":"api-019","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> a = new ArrayList<>();\n        a.add(null);\n        System.out.println(a.size());\n        List<String> b = List.of(\"x\", null);\n        System.out.println(b.size());\n    }\n}","choices":["1 と 2 が表示される","1 と表示された後、NullPointerException がスローされる","何も表示されずに NullPointerException がスローされる","8行目でコンパイルエラー"],"answer":[1],"explain":"ArrayList には null を追加できる。List.of は要素に null があると、リストを作る時点で NullPointerException をスローする。なお、List.of で作ったリストは変更できず、add や set は UnsupportedOperationException になる。","topic":"配列とリスト","sub":"List"},{"id":"api-020","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> names = new ArrayList<>();\n        names.add(new String(\"red\"));\n        List<StringBuilder> sbs = new ArrayList<>();\n        sbs.add(new StringBuilder(\"red\"));\n        System.out.println(names.contains(\"red\") + \" \" + names.indexOf(\"red\") + \" \" + sbs.contains(new StringBuilder(\"red\")));\n    }\n}","choices":["true 0 false","false -1 false","true 0 true","false -1 true","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"contains や indexOf は == ではなく equals で要素を比べる。String は equals が中身を比べるようにオーバーライドされているので、new String で作った別オブジェクトでも見つかる。StringBuilder は equals をオーバーライドしていないため、Object の equals（同じオブジェクトかどうか）で比べられ、中身が同じでも false になる。","topic":"配列とリスト","mono":1,"sub":"List"},{"id":"api-021","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> list = new ArrayList<>(List.of(\"a\", \"b\", \"c\", \"d\"));\n        for (String s : list) {\n            if (s.equals(\"b\")) {\n                list.remove(s);\n            }\n        }\n        System.out.println(list);\n    }\n}","choices":["[a, c, d] と表示される","実行時に ConcurrentModificationException がスローされる","実行時に UnsupportedOperationException がスローされる","コンパイルエラー"],"answer":[1],"explain":"拡張 for 文は内部でイテレータを使っており、ループ中にリスト自身の remove で要素数を変えると、次の要素を取り出すときに ConcurrentModificationException がスローされる。ただし最後から2番目の要素を消した場合は、hasNext() が false になってループがそのまま終わるので例外にならない（このコードで \"c\" を消すと [a, b, d] と表示される）。ループ中に要素を取り除きたいときは removeIf（またはイテレータの remove）を使う。new ArrayList<>(List.of(...)) は変更できるリストなので、UnsupportedOperationException にはならない。","topic":"配列とリスト","sub":"List"},{"id":"api-022","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> nums = new ArrayList<>(List.of(1, 2, 3, 4, 5, 6));\n        nums.removeIf(n -> n % 3 == 0);\n        nums.replaceAll(n -> n * n);\n        nums.forEach(n -> System.out.print(n + \" \"));\n    }\n}","choices":["1 4 16 25","9 36","1 2 4 5","1 4 9 16 25 36","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"removeIf は条件が true になる要素を取り除く（ここでは 3 と 6）。replaceAll は各要素をラムダの戻り値で置き換え、forEach は各要素に順番に処理を行う。どれもリストそのものに対して働く。","topic":"配列とリスト","mono":1,"sub":"List"},{"id":"api-023","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> nums = new ArrayList<>(List.of(10, 20, 10, 30));\n        boolean r = nums.remove(Integer.valueOf(10));\n        int x = nums.remove(0);\n        System.out.println(r + \" \" + x + \" \" + nums);\n    }\n}","choices":["true 20 [10, 30]","true 20 [30]","true 10 [20, 30]","実行時に IndexOutOfBoundsException がスローされる","コンパイルエラー"],"answer":[0],"explain":"remove(Object) は equals で一致する最初の1つだけを取り除き、取り除けたかどうかを boolean で返す。remove(int) は指定した添字の要素を取り除き、その要素を返す。Integer.valueOf(10) は Integer 型なので remove(Object) が選ばれ、添字10とはみなされない。","topic":"配列とリスト","mono":1,"sub":"List"},{"id":"api-024","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ（java.util は完全修飾名で書いている）。","choices":["java.util.List<Integer> l = java.util.List.of(1, 2);\nl.add(3);","int[] a = {1, 2};\njava.util.List<Integer> l = java.util.Arrays.asList(a);","Integer[] a = {1, 2};\njava.util.List<Integer> l = java.util.Arrays.asList(a);","java.util.List<String> l = new java.util.ArrayList<>();\nl.replaceAll(s -> s.length());","java.util.ArrayList<Integer> l = java.util.List.of(1, 2);","java.util.List<String> l = new java.util.ArrayList<>();\nl.removeIf(s -> s.isEmpty());"],"answer":[1,3,4],"explain":"List.of のリストへの add は、実行時に UnsupportedOperationException になるだけでコンパイルは通る。Arrays.asList に int[] を渡すと「int[] を1要素とするリスト」になり、List<Integer> には代入できない（Integer[] なら可）。replaceAll のラムダは要素と同じ型（ここでは String）を返す必要がある。List.of の戻り値の型は List なので、ArrayList 型の変数には代入できない。","topic":"配列とリスト","mono":1,"sub":"List"},{"id":"api-025","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.Arrays;\n\npublic class Main {\n    public static void main(String[] args) {\n        String[] s = {\"10\", \"9\", \"100\", \"1\"};\n        int[] n = {10, 9, 100, 1};\n        Arrays.sort(s);\n        Arrays.sort(n);\n        System.out.println(Arrays.toString(s) + \" \" + Arrays.toString(n));\n    }\n}","choices":["[1, 10, 100, 9] [1, 9, 10, 100]","[1, 9, 10, 100] [1, 9, 10, 100]","[1, 10, 100, 9] [1, 10, 100, 9]","[10, 9, 100, 1] [1, 9, 10, 100]","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"Arrays.sort は配列そのものを昇順に並べ替える。String は辞書順（先頭から1文字ずつ文字コードで比較）で並ぶので、\"100\" は \"9\" より前に来る。int は数値の大小で並ぶ。Arrays.toString は [要素, 要素, …] の形の文字列を返す。","topic":"配列とリスト","mono":1,"sub":"配列"},{"id":"api-026","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.Arrays;\n\npublic class Main {\n    public static void main(String[] args) {\n        int[] a = {1, 2, 3};\n        int[] b = {1, 2, 3};\n        int[] c = a;\n        System.out.println((a == b) + \" \" + a.equals(b) + \" \" + Arrays.equals(a, b) + \" \" + (a == c));\n    }\n}","choices":["false false true true","false true true true","true true true true","false false false true","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"配列の == は同じオブジェクトかどうかを比べる。配列は equals をオーバーライドしていないので、a.equals(b) も == と同じ結果になる。要素の中身を比べるには Arrays.equals を使う。","topic":"配列とリスト","mono":1,"sub":"配列"},{"id":"api-027","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ（java.util は完全修飾名で書いている）。","choices":["int[] a = {3, 1};\nint[] b = java.util.Arrays.sort(a);","int[] a = {3, 1};\nString s = java.util.Arrays.toString(a);","int[] a = {1};\nlong[] b = {1L};\nboolean r = java.util.Arrays.equals(a, b);","int[] a = {1, 2};\nint[] b = a.clone();","int[] a = {1, 2};\nlong[] b = a;","String[] a = {\"b\", \"a\"};\njava.util.Arrays.sort(a);\nObject[] o = a;"],"answer":[0,2,4],"explain":"Arrays.sort は配列そのものを並べ替えるメソッドで、戻り値は void。int[] と long[] は別の型で、int → long のような拡大変換は配列には効かないため、代入も Arrays.equals(int[], long[]) の呼び出しもできない。参照型の配列は String[] → Object[] のように代入でき、clone は同じ型の配列のコピーを返す。","topic":"配列とリスト","mono":1,"sub":"配列"},{"id":"conv2-001","type":"single","q":"次のコードをコンパイル・実行するとどうなる？（'C' の文字コードは 67）","code":"char c = 'C';\nint i = c;\nchar d = (char) (i + 1);\nSystem.out.println(i + \" \" + d);","choices":["67 D","C D","67 68","C 68","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"i は int 型なので、c の文字コード 67 が数値のまま表示される。d は char 型なので、68 は文字として読まれ D になる。見るのは元の値ではなく、代入先の変数の型。char → int は自動だが、int → char は縮小なので、i のような変数から代入するにはキャストが必要（char d = 68; のように範囲内の定数を代入する場合は不要）。","topic":"型変換","mono":1},{"id":"conv2-002","type":"single","q":"次のコードをコンパイル・実行するとどうなる？（'A' の文字コードは 65）","code":"char c = 'A';\nSystem.out.println(c + 1);\nSystem.out.println((char) (c + 1));","choices":["66\nB","B\nB","66\n66","A1\nB","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"char に数値を足すと、char は計算の前に int へ拡大されるので、2行目の c + 1 の結果は int の 66。println には int が渡るので 66 と表示される。3行目は計算結果を (char) で char に戻しているので、66 が文字として読まれ B になる。表示の形を決めるのは元の c の型ではなく、最後に渡った値の型。","topic":"型変換","mono":1},{"id":"conv2-003","type":"single","q":"次のコードをコンパイル・実行するとどうなる？（'A' の文字コードは 65、'B' は 66）","code":"System.out.println('A' + 'B');\nSystem.out.println(\"\" + 'A' + 'B');\nSystem.out.println('A' + 'B' + \"\");","choices":["131\nAB\n131","AB\nAB\nAB","131\nAB\nAB","131\n131\n131","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"+ は左から順に計算される。char 同士の + は数値の足し算になり、int の 131（65 + 66）になる。先頭が文字列 \"\" なら、そこから先は文字列の連結になり \"A\" → \"AB\" とつながる。3行目は先に 'A' + 'B' が 131 になってから \"\" と連結されるので、文字列の \"131\"。","topic":"型変換","mono":1},{"id":"conv2-004","type":"single","q":"次のコードをコンパイル・実行するとどうなる？（'A' の文字コードは 65）","code":"char c = 'A';\ndouble d = c;\nSystem.out.println(d);","choices":["65.0","65","A","2行目でコンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"char → double は拡大方向なのでキャスト不要（char → int / long / float / double はすべて自動）。d は double 型なので、文字コードの 65 が小数の形 65.0 で表示される。文字の A でも整数の 65 でもなく、代入先の double の形になる。","topic":"型変換","mono":1},{"id":"conv2-005","type":"single","q":"次のコードをコンパイル・実行するとどうなる？（'A' の文字コードは 65）","code":"Object o = 'A';\nObject p = 'A' + 1;\nSystem.out.println(o + \" \" + p);","choices":["A 66","65 66","A B","65 B","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"Object に基本データ型の値を入れると、その値の型に対応するラッパーにボクシングされる。'A' は char なので Character になり、表示は A。'A' + 1 は計算した時点で int の 66 なので Integer になり、表示は 66。Object 型に入れても数値に直されるわけではなく、中身のオブジェクトの形で表示される。","topic":"型変換","mono":1,"sub":"ボクシング"},{"id":"conv2-006","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"int i = 3;\nlong l = 4L;\nfloat f = i;\ndouble d = l;\nSystem.out.println(f + \" \" + d);\nSystem.out.println(i + l);\nSystem.out.println(f + d);","choices":["3.0 4.0\n7\n7.0","3 4\n7\n7","3.0 4.0\n7.0\n7.0","3 4\n7\n7.0","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"int → float、long → double は拡大なので自動で変換され、代入先の f と d は小数の形 3.0 と 4.0 で表示される。見るのは元の値ではなく、代入先の型。計算結果は大きい方の型にそろうので、int + long は long の 7、float + double は double の 7.0 になる。","topic":"型変換","mono":1},{"id":"conv2-007","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"double a = 7 / 2;\ndouble b = 7 / 2.0;\nint c = 7 / 2;\nSystem.out.println(a + \" \" + b + \" \" + c);","choices":["3.0 3.5 3","3.5 3.5 3","3 3.5 3","3.0 3.5 3.0","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"7 / 2 は int 同士の割り算なので、代入より先に 3 に切り捨てられる。その 3 を double の a に入れると 3.0、int の c に入れると 3 と表示される（同じ値でも、表示は代入先の型で決まる）。7 / 2.0 は片方が double なので double の割り算になり 3.5。","topic":"型変換","mono":1},{"id":"conv2-008","type":"multi","q":"コンパイルが通るものを【すべて】選べ。","choices":["byte b = 1;\nshort s = b;","float f = 1.5f;\nlong l = f;","long l = 5L;\ndouble d = l;","float f = 1.5;","short s = 3;\nbyte b = s;","int i = 7;\nlong l = i;\nfloat f = l;"],"answer":[0,2,5],"explain":"byte → short → int → long → float → double の向き（右へ進む向き）は自動で変換される。逆向きは隣どうしでも原則としてキャストが必要（float → long、short → byte）。例外は、byte・short・char・int 型の定数式（リテラルや、定数で初期化した final 変数）の値が代入先の範囲に収まるときで、byte・short・char へはキャスト無しで代入できる。short s = 3; byte b = s; の s は final でないので定数とみなされずエラーだが、final short s = 3; なら byte b = s; も通る。1.5 のような小数リテラルは double 型で、double の定数にはこの例外が無いので、float に入れるには 1.5f と書くかキャストする。","topic":"型変換","mono":1},{"id":"conv2-009","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["char c = 'A';\nlong l = c;","short s = 65;\nchar c = s;","char c = 'A';\nfloat f = c;","int i = 66;\nchar c = i;","char c = 'A';\nbyte b = c;","byte b = 65;\nchar c = (char) b;"],"answer":[1,3,4],"explain":"char → int / long / float / double は拡大なので自動で変換される。char と byte・short の間は、どちら向きでもキャストが必要（char は 0〜65535 で負の数を持たず、範囲が食い違うため）。int → char も縮小なのでキャストが必要。ただし short s = 65; や char c = 65; のように、範囲内の定数を代入する場合は例外で、キャスト無しで通る。定数で初期化した final 変数も定数として扱われるので、final short s = 65; なら char c = s; も、final char c = 'A'; なら byte b = c; も通る（問題の s や c は final でないのでエラー）。","topic":"型変換","mono":1},{"id":"conv2-010","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"double d = -3.7;\nint a = (int) d * 2;\nint b = (int) (d * 2);\nSystem.out.println(a + \" \" + b);","choices":["-6 -7","-7 -7","-8 -8","-8 -7","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"浮動小数点数 → 整数のキャストは、四捨五入でも切り下げでもなく 0 の方向への切り捨て（小数部を捨てるだけ）なので、-3.7 → -3、-7.4 → -7 になる。(int) はすぐ右の d だけにかかるので、a は -3 * 2 = -6。b は先に d * 2 = -7.4 を計算してからキャストするので -7。","topic":"型変換","mono":1},{"id":"conv2-011","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"double d = (int) 7.9 / 2;\nSystem.out.println(d);","choices":["3.0","3.5","3","4.0","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"(int) は直後の 7.9 だけにかかり、小数部が捨てられて 7 になる（四捨五入ではないので 8 にはならない）。7 / 2 は int 同士の割り算なので 3。最後に double の d に入るので 3.0 と表示される。「キャスト → 割り算 → 代入」の順に、その時点の型で計算が進む。","topic":"型変換","mono":1},{"id":"conv2-012","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"char c = 'A';\nchar d = c + 1;\nSystem.out.println(d);","choices":["B","66","2行目でコンパイルエラー","3行目でコンパイルエラー"],"answer":[2],"explain":"char に数値を足した c + 1 の結果は int 型。int → char は縮小なので、そのままでは char に代入できない（possible lossy conversion from int to char）。char d = (char) (c + 1); と書けば B と表示される。なお c += 1; なら複合代入演算子が暗黙にキャストするので通る。また c を final char c = 'A'; と宣言していれば、c + 1 は値が決まった定数式（66）になり、char の範囲に収まるのでキャスト無しで代入できる。","topic":"型変換"},{"id":"conv2-013","type":"single","q":"次のコードをコンパイル・実行するとどうなる？（'A' の文字コードは 65）","code":"public class Main {\n    static void show(int x) {\n        System.out.print(x + \" \");\n    }\n    static void show(Character x) {\n        System.out.print(x + \" \");\n    }\n    public static void main(String[] args) {\n        char c = 'A';\n        show(c);\n        show(Character.valueOf('B'));\n    }\n}","choices":["65 B","A B","65 66","A 66","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"オーバーロードの選択は「完全一致 → 拡大変換 → ボクシング → 可変長引数」の順。char の c は、ボクシングで Character にするより先に、拡大変換で受け取れる show(int) が選ばれる。引数 x は int 型なので 65 と表示される（見るのは渡した値ではなく、受け取る側の型）。Character を渡した2回目は show(Character) と完全に一致するので B。","topic":"型変換","mono":1,"sub":"ボクシング"},{"id":"conv2-014","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"Long l = 10L;\nSystem.out.println(l.equals(10));\nSystem.out.println(l == 10);\nSystem.out.println(l.equals(10L));","choices":["false\ntrue\ntrue","true\ntrue\ntrue","false\nfalse\ntrue","true\nfalse\ntrue","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"equals の引数は Object 型なので、10 は int → Integer にボクシングされて渡る。Long の equals は「相手も Long で値が同じ」ときだけ true なので、Integer の 10 とは false。l == 10 は l がアンボクシングされ、数値どうしで比べられるので true。l.equals(10L) なら Long 同士なので true。","topic":"型変換","mono":1,"sub":"ボクシング"},{"id":"conv2-015","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"Integer[] scores = new Integer[3];\nscores[0] = 80;\nint total = 0;\nfor (int s : scores) {\n    total += s;\n}\nSystem.out.println(total);","choices":["80 と表示される","80 と表示された後、NullPointerException がスローされる","実行時に NullPointerException がスローされる","4行目でコンパイルエラー"],"answer":[2],"explain":"Integer などのラッパー型の配列は、要素の初期値が 0 ではなく null。拡張 for の変数 s は int 型なので、要素を取り出すたびにアンボクシングが起きる。2つ目の要素は null なので、ループの途中（println より前）で NullPointerException になる。int[] なら初期値は 0 なので 80 と表示される。","topic":"型変換","sub":"ボクシング"},{"id":"conv2-016","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static void show(Object o) {\n        System.out.print(\"Object \");\n    }\n    static void show(int... a) {\n        System.out.print(\"int... \");\n    }\n    public static void main(String[] args) {\n        show(10);\n        show(10, 20);\n    }\n}","choices":["Object int...","int... int...","9行目でコンパイルエラー","10行目でコンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"オーバーロードは「完全一致 → 拡大変換 → ボクシング → 可変長引数」の順に候補を探し、先の段階で見つかればそこで決まる。show(10) は int → Integer にボクシングすれば Object として受け取れるので、最後の段階の可変長引数より先に show(Object) が選ばれる。引数が2つの show(10, 20) を受け取れるのは可変長引数だけ。","topic":"型変換","mono":1,"sub":"ボクシング"},{"id":"conv2-017","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"boolean flag = true;\nInteger i = 1;\nDouble d = 2.0;\nObject o = flag ? i : d;\nSystem.out.println(o);","choices":["1.0","1","2.0","4行目でコンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"条件演算子の2つの候補が Integer と Double のように種類の違う数値の場合、どちらもアンボクシングされて大きい方の double にそろえられる（数値昇格）。そのため選ばれたのは i なのに、式全体の値は double の 1.0 になり、Object には Double として入る。表示の形を決めるのは i の型ではなく、式全体の型。","topic":"型変換","mono":1,"sub":"ボクシング"},{"id":"conv2-018","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static long twice(long n) {\n        return n * 2;\n    }\n    static Long same(Long n) {\n        return n;\n    }\n    public static void main(String[] args) {\n        System.out.println(twice(Integer.valueOf(5)));\n        System.out.println(same(5));\n    }\n}","choices":["10\n5","9行目でコンパイルエラー","10行目でコンパイルエラー","9行目と10行目でコンパイルエラー"],"answer":[2],"explain":"アンボクシングの後なら拡大変換してよいので、Integer → int → long と変換でき、9行目は通る。一方、ボクシングは int → Integer のように対応するラッパーにしかできず、int を直接 Long にはできない（拡大してからボクシング、は不可）。10行目は same(5L) と書けば通る。","topic":"型変換","sub":"ボクシング"},{"id":"conv2-019","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["Integer i = 'A';","Object o = 10;","Long l = Integer.valueOf(1);","double d = Long.valueOf(3);","Number n = 3.5;","Integer i = 5;\nshort s = i;"],"answer":[0,2,5],"explain":"ボクシングは原則として char → Character、int → Integer のように対応するラッパーにしかできず、char → Integer のように型をまたげない（例外は代入のときの定数だけで、範囲内の定数なら Byte・Short・Character には入れられる。Short s = 5; や Character c = 65; は通るが、Long l = 5; や Integer i = 'A'; は通らない）。Integer と Long は親子関係の無い別のクラスなので、代入もできない。アンボクシングの後は拡大（Long → long → double）はできるが、縮小（Integer → int → short）はできない。Object や Number には、ボクシングしたラッパー（Integer・Double）を親の型として入れられる。","topic":"型変換","mono":1,"sub":"ボクシング"},{"id":"conv2-020","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Animal { }\nclass Dog extends Animal { }\npublic class Main {\n    public static void main(String[] args) {\n        Dog d1 = new Dog();\n        Animal a = d1;\n        Dog d2 = a;\n        System.out.println(d1 == d2);\n    }\n}","choices":["true と表示される","6行目でコンパイルエラー","7行目でコンパイルエラー","実行時に ClassCastException が発生する"],"answer":[2],"explain":"子 → 親（Dog → Animal）のアップキャストは暗黙に行われるので、6行目は通る。親 → 子（Animal → Dog）のダウンキャストは、中身が本当に Dog かをコンパイラが保証できないため、(Dog) a と明示的なキャストが必要。コンパイラが見るのは変数 a の型（Animal）であって、中身のオブジェクトではない。Dog d2 = (Dog) a; なら true と表示される。","topic":"型変換","sub":"参照型の型変換"},{"id":"conv2-021","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Animal { }\nclass Dog extends Animal { }\npublic class Main {\n    public static void main(String[] args) {\n        Animal a = new Animal();\n        System.out.print(\"start \");\n        Dog d = (Dog) a;\n        System.out.println(\"end\");\n    }\n}","choices":["start end と表示される","7行目でコンパイルエラー","start と表示された後、ClassCastException がスローされる","何も表示されずに ClassCastException がスローされる"],"answer":[2],"explain":"Animal 型から Dog 型へのキャストは、中身が Dog の可能性があるのでコンパイルは通る。しかし実際のオブジェクトは new Animal() で作った Animal そのもので、Dog ではない。キャストはオブジェクトを作り替えないので、実行時にキャストの行で ClassCastException になる（その前の start は表示済み）。","topic":"型変換","sub":"参照型の型変換"},{"id":"conv2-022","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Animal { }\nclass Dog extends Animal { }\nclass Cat extends Animal { }\npublic class Main {\n    public static void main(String[] args) {\n        Dog d = new Dog();\n        Animal a = d;\n        Cat c1 = (Cat) a;\n        Cat c2 = (Cat) d;\n    }\n}","choices":["何も表示されずに正常終了する","8行目でコンパイルエラー","9行目でコンパイルエラー","実行時に8行目で ClassCastException が発生する"],"answer":[2],"explain":"クラスどうしのキャストがコンパイルできるかは、変数の型（宣言した型）どうしに親子関係があるかで決まる。8行目は Animal → Cat なので「中身が Cat かもしれない」として通る（実行すれば ClassCastException になる）。9行目の Dog と Cat はどちらも相手の子ではないので、中身を見るまでもなくコンパイルエラー。コンパイルエラーがあるとプログラムは実行されない。","topic":"型変換","sub":"参照型の型変換"},{"id":"conv2-023","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["Number n = 1;\nInteger i = n;","Number n = 1;\nInteger i = (Integer) n;","Integer i = 1;\nLong l = (Long) i;","Number n = 1;\nRunnable r = (Runnable) n;","Integer i = 1;\nRunnable r = (Runnable) i;","String s = \"Java\";\nCharSequence cs = s;"],"answer":[0,2,4],"explain":"親 → 子（Number → Integer）はキャストを書けば通るが、書かないとエラー。Integer と Long はどちらも Number の子だが互いに親子ではないので、キャストしてもエラー。インターフェースへのキャストは、元のクラスが final でなければ「子クラスが実装しているかもしれない」ので通る（Number）が、final クラスの Integer は Runnable を実装していないと確定しているのでエラー。String → CharSequence は実装しているインターフェースへのアップキャストなので、キャスト無しで通る。","topic":"型変換","mono":1,"sub":"参照型の型変換"},{"id":"conv2-024","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Animal { }\nclass Dog extends Animal {\n    String bark() { return \"Woof\"; }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Animal[] animals = { new Dog(), new Animal(), null };\n        for (Animal a : animals) {\n            if (a instanceof Dog) {\n                Dog d = (Dog) a;\n                System.out.print(d.bark() + \" \");\n            } else {\n                System.out.print(\"skip \");\n            }\n        }\n    }\n}","choices":["Woof skip skip","Woof skip","Woof skip の後、NullPointerException がスローされる","Woof の後、ClassCastException がスローされる","コンパイルエラー"],"answer":[0],"explain":"instanceof は、変数の型ではなく実行時の中身のオブジェクトで判定する。2つ目の中身は Animal そのものなので false、3つ目の null はどの型に対しても false になる（例外は出ない）。true の時だけキャストしているので、ClassCastException も NullPointerException も起きない。ダウンキャストの前に instanceof で確かめるのが定石。","topic":"型変換","mono":1,"sub":"参照型の型変換"},{"id":"conv2-025","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"Object[] items = new String[2];\nitems[0] = \"pen\";\nSystem.out.println(items[0]);\nitems[1] = Integer.valueOf(1);\nSystem.out.println(items[1]);","choices":["pen と 1 が表示される","4行目でコンパイルエラー","pen と表示された後、ArrayStoreException がスローされる","pen と表示された後、ClassCastException がスローされる"],"answer":[2],"explain":"String[] は Object[] の一種として扱えるので、1行目の代入は通る。コンパイラは items を Object[] として見るので、4行目の Integer の代入もコンパイルは通る。しかし実際の配列は String[] なので、実行時に String 以外を入れた時点で ArrayStoreException になる。","topic":"型変換","sub":"参照型の型変換"},{"id":"conv2-026","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Cup {\n    public String toString() { return \"Cup\"; }\n}\nclass TeaCup extends Cup {\n    public String toString() { return \"TeaCup\"; }\n}\npublic class Main {\n    public static void main(String[] args) {\n        TeaCup t = new TeaCup();\n        Cup c = t;\n        Object o = c;\n        System.out.println(t + \" \" + c + \" \" + o);\n    }\n}","choices":["TeaCup TeaCup TeaCup","TeaCup Cup Cup","TeaCup Cup Object","11行目でコンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"参照型の代入（アップキャスト）は、オブジェクトを作り替えずに「どの型として見るか」だけを変える。c も o も指しているのは同じ TeaCup のオブジェクトなので、オーバーライドされた TeaCup の toString() が呼ばれる。基本データ型の変換（int → double で 5 が 5.0 になる）と違い、参照型では中身の形は変わらない。","topic":"型変換","mono":1,"sub":"参照型の型変換"},{"id":"conv2-027","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Animal {\n    String sound() { return \"...\"; }\n}\nclass Dog extends Animal {\n    String sound() { return \"Woof\"; }\n    String fetch() { return \"Ball\"; }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Animal a = new Dog();\n        System.out.println(a.sound());\n        System.out.println((Dog) a.fetch());\n    }\n}","choices":["Woof\nBall","...\nBall","12行目でコンパイルエラー","実行時に ClassCastException が発生する"],"answer":[2],"explain":"メソッド呼び出しの . はキャストより先に結び付くので、(Dog) a.fetch() は (Dog) (a.fetch()) の意味になる。a の型は Animal で、Animal に fetch() は無いのでコンパイルエラー（呼べるメソッドは変数の型で決まる）。((Dog) a).fetch() と書けば Ball。なお a.sound() はオーバーライドされているので、中身の Dog の sound() が動き Woof になる。","topic":"型変換","sub":"参照型の型変換"},{"id":"mix-001","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Animal {\n    String name = \"animal\";\n    static String kind() { return \"A\"; }\n    String call() { return \"...\"; }\n    String info() { return kind() + \":\" + name + \":\" + call(); }\n}\nclass Dog extends Animal {\n    String name = \"dog\";\n    static String kind() { return \"D\"; }\n    @Override\n    String call() { return \"wan\"; }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Animal a = new Dog();\n        Dog d = (Dog) a;\n        System.out.println(a.name + \" \" + a.kind() + \" \" + a.call());\n        System.out.println(d.name + \" \" + d.kind() + \" \" + d.call());\n        System.out.println(d.info());\n    }\n}","choices":["animal A wan\ndog D wan\nA:animal:wan","dog D wan\ndog D wan\nD:dog:wan","animal A wan\ndog D wan\nD:dog:wan","animal D wan\ndog D wan\nA:animal:wan","animal A ...\ndog D wan\nA:animal:...","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"フィールドと static メソッドはオーバーライドされず、どれが使われるかは変数の宣言型（コンパイル時の型）で決まる。a は Animal 型なので a.name は \"animal\"、a.kind() は Animal の \"A\" だが、インスタンスメソッドの call() はオーバーライドされているので実体の Dog 版 \"wan\" が呼ばれる。d は Dog 型なので、2つ目の println は dog D wan。info() は Animal に書かれたメソッドなので、中の kind() と name は Animal のものにコンパイル時に決まり、call() だけが実体に応じて Dog 版になるため A:animal:wan。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-002","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    public static void main(String[] args) {\n        int[][] data = { {2, 4}, {3, 1, 7}, {5, 0}, {6, 9, 1}, {8} };\n        int total = 0;\n        outer:\n        for (int i = 0; i < data.length; i++) {\n            for (int j = 0; j < data[i].length; j++) {\n                if (data[i][j] == 1) {\n                    continue outer;\n                }\n                if (data[i][j] > 8) {\n                    break outer;\n                }\n                total += data[i][j];\n            }\n            total += 10;\n        }\n        System.out.println(total);\n    }\n}","choices":["40","57","68","85","50","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"continue outer は内側のループを抜けて外側ループの次の周回（i++）へ進むので、その周回の total += 10 は実行されない。break outer は外側ループごと終了させる。i=0 は 2+4 に 10 を足して 16、i=1 は 3 を足した後の 1 で continue outer するので 7 と +10 は飛ばされて 19、i=2 は 5+0 と +10 で 34。i=3 は 6 を足して 40 になった後、9 で break outer するので、+10 も最後の配列 {8} も処理されず 40 が表示される。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-003","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static int score(String grade) {\n        return switch (grade) {\n            case \"A\", \"S\" -> 3;\n            case \"B\" -> {\n                int base = 1;\n                yield base + 1;\n            }\n            default -> 0;\n        };\n    }\n    public static void main(String[] args) {\n        String[] grades = {\"A\", \"b\", \"B\"};\n        int total = 0;\n        for (String g : grades) {\n            switch (score(g)) {\n                case 3:\n                    total += 10;\n                case 2:\n                    total += 5;\n                    break;\n                case 0:\n                    total -= 1;\n                default:\n                    total += 100;\n            }\n        }\n        System.out.println(total);\n    }\n}","choices":["119","25","14","19","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"score() の switch 式はアロー形式なのでフォールスルーせず、\"A\" は 3、\"B\" は 2 を返す。String の case は equals で比べるので大文字・小文字を区別し、\"b\" はどの case にも一致せず default の 0 になる。一方 main の switch 文はコロン形式なので、break が無い限り下の case へ落ちていく。\"A\"（3）は +10 の後 case 2 に落ちて +5 で break（計15）、\"b\"（0）は -1 の後 default に落ちて +100（計114）、\"B\"（2）は +5 で break して 119。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-004","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    public static void main(String[] args) {\n        String[] inputs = {\"10\", \"x\", \"0\", \"5\", \"-3\", \"4\"};\n        StringBuilder log = new StringBuilder();\n        for (String s : inputs) {\n            try {\n                int n = Integer.parseInt(s);\n                if (n == 0) {\n                    continue;\n                }\n                if (n < 0) {\n                    break;\n                }\n                log.append(100 / n);\n            } catch (NumberFormatException e) {\n                log.append(\"E\");\n                continue;\n            } finally {\n                log.append(\"|\");\n            }\n            log.append(\";\");\n        }\n        System.out.println(log);\n    }\n}","choices":["10|;E||20|;|","10|;E20|;","10|;E||20|;","10|;E||20|;|25|;","実行時に例外（ArithmeticException）がスローされて異常終了する","コンパイルエラー"],"answer":[0],"explain":"finally ブロックは、try や catch の中で continue・break によって制御が移る場合でも、移る直前に必ず実行される。\"10\" は 10 を追加し、finally の | と最後の ; が付いて 10|;。\"x\" は NumberFormatException で E を追加し、continue で次の周回へ移る前に | が付く（; は飛ばされる）。\"0\" は割り算の前に continue するので ArithmeticException は起きず、| だけが付く。\"5\" は 20|;、\"-3\" は break でループを抜ける前に | が付き、最後の \"4\" は処理されない。\"x\" で発生する NumberFormatException は catch で処理されるので、プログラムが例外で異常終了することはない。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-005","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Base {\n    static { System.out.print(\"S1 \"); }\n    { System.out.print(\"I1 \"); }\n    Base() {\n        this(7);\n        System.out.print(\"B \");\n    }\n    Base(int n) {\n        System.out.print(\"B\" + n + \" \");\n        init();\n    }\n    void init() { System.out.print(\"base \"); }\n}\nclass Sub extends Base {\n    int size = 5;\n    static { System.out.print(\"S2 \"); }\n    { System.out.print(\"I2 \"); }\n    Sub() {\n        System.out.print(\"C\" + size + \" \");\n    }\n    @Override\n    void init() { System.out.print(\"init\" + size + \" \"); }\n}\npublic class Main {\n    public static void main(String[] args) {\n        new Sub();\n        System.out.println();\n        new Sub();\n    }\n}","choices":["S1 S2 I1 B7 init0 B I2 C5\nI1 B7 init0 B I2 C5","S1 S2 I1 B7 init5 B I2 C5\nI1 B7 init5 B I2 C5","S1 S2 I1 B7 base B I2 C5\nI1 B7 base B I2 C5","S1 S2 I1 B7 init0 B I2 C5\nS1 S2 I1 B7 init0 B I2 C5","S1 I1 B7 init0 B S2 I2 C5\nI1 B7 init0 B I2 C5","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"クラスの初期化は最初の new Sub() のときに1回だけ行われ、親から順に static 初期化子が動いて S1 S2 と出る（2回目の new では出ない）。Sub() の先頭の暗黙の super() で Base() が呼ばれ、this(7) で Base(int) へ移る。インスタンス初期化子は this(...) で始まるコンストラクタでは実行されず、super()（暗黙）を呼ぶ Base(int) の本体の前で1回だけ実行されるので I1、続いて B7。そこで呼ぶ init() はオーバーライドされた Sub 版だが、Sub のフィールドはまだ初期化前なので size は 0 で init0 になる。this(7) から戻って Base() の残りの B が出た後、Sub のフィールド初期化（size = 5）と初期化子 I2 が実行され、最後に Sub() の本体が C5 を出す。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-006","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static final String HEAD = \"ja\";\n\n    public static void main(String[] args) {\n        final String a = \"va\";\n        String b = \"va\";\n        final String c = b;\n        String full = \"java\";\n        String s1 = HEAD + a;\n        String s2 = HEAD + b;\n        String s3 = HEAD + c;\n        String s4 = \"ja\" + \"va\";\n        String s5 = s2.intern();\n        System.out.println((full == s1) + \" \" + (full == s2) + \" \" + (full == s3));\n        System.out.println((full == s4) + \" \" + (full == s5) + \" \" + full.equals(s3));\n    }\n}","choices":["true false false\ntrue true true","true false true\ntrue true true","false false false\ntrue false true","true true true\ntrue true true","false false false\ntrue true true","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"リテラルと「宣言時に定数で初期化された final 変数」だけでできた式（定数式）の連結はコンパイル時に計算され、文字列プールにある \"java\" と同じオブジェクトになる。HEAD と a はこの条件を満たすので s1 は == で true、リテラル同士の s4 も true。b は final でないので s2 は実行時に新しい String が作られて false、c は final だが、初期化に使った b が定数ではないので定数扱いにならず（定数になるのは、宣言時に定数式で初期化した final 変数だけ）、s3 も実行時に新しい String が作られて false。intern() はプール上の同じ内容のオブジェクトを返すので s5 は true、full.equals(s3) は中身を比べるので true。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-007","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"interface Greeter {\n    default String greet() { return \"Hello\"; }\n    String name();\n}\ninterface Polite extends Greeter {\n    @Override\n    default String greet() { return \"Good day\"; }\n}\nabstract class Person implements Greeter {\n    public String greet() { return \"Hi, \" + name(); }\n}\nclass Staff extends Person implements Polite {\n    public String name() { return \"Sato\"; }\n}\nclass Guest implements Polite {\n    public String name() { return \"Guest\"; }\n    public String greet() { return Polite.super.greet() + \", \" + name(); }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Greeter g1 = new Staff();\n        Greeter g2 = new Guest();\n        System.out.println(g1.greet());\n        System.out.println(g2.greet());\n    }\n}","choices":["Hi, Sato\nGood day, Guest","Good day\nGood day, Guest","Hello\nHello, Guest","Hi, Sato\nHello, Guest","12行目でコンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"スーパークラスから継承した public なインスタンスメソッドとインターフェースの default メソッドが衝突した場合は、クラス側が優先される（コンパイルエラーにはならない）。ただし、クラス側のメソッドが public でない場合（インターフェースの public なメソッドのアクセスを狭めることになる）や static の場合はコンパイルエラーになる。Staff には Person の public な greet() と Polite の default の greet() という2つの候補があるが、クラス側の Person の greet() が選ばれ、name() は Staff の実装なので \"Hi, Sato\"。Guest は greet() をオーバーライドし、「インターフェース名.super.メソッド名()」の形で Polite の default メソッドを呼んでいるので \"Good day, Guest\"。変数の型が Greeter でも、実行されるのは実体のクラスで決まったメソッドである。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-008","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.ArrayList;\nimport java.util.List;\n\nrecord Point(int x, int y) {\n    Point {\n        if (x < 0) x = 0;\n    }\n}\nclass Spot {\n    final int x, y;\n    Spot(int x, int y) { this.x = x; this.y = y; }\n}\npublic class Main {\n    public static void main(String[] args) {\n        List<Point> points = new ArrayList<>();\n        points.add(new Point(-5, 2));\n        points.add(new Point(3, 4));\n        List<Spot> spots = new ArrayList<>();\n        spots.add(new Spot(3, 4));\n        System.out.println(points.contains(new Point(0, 2)));\n        System.out.println(points.indexOf(new Point(3, 4)));\n        System.out.println(spots.contains(new Spot(3, 4)));\n        System.out.println(points.get(0));\n    }\n}","choices":["true\n1\nfalse\nPoint[x=0, y=2]","false\n1\nfalse\nPoint[x=-5, y=2]","true\n1\ntrue\nPoint[x=0, y=2]","false\n-1\nfalse\nPoint[x=-5, y=2]","6行目でコンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"コンパクトコンストラクタの中では引数を代入し直すことができ、本体の最後にその値がフィールドへ代入される。そのため new Point(-5, 2) のフィールドは x=0, y=2 になる。record は全コンポーネントを比べる equals() を自動生成するので、contains(new Point(0, 2)) は true、indexOf(new Point(3, 4)) は 1。Spot は equals() をオーバーライドしていないので Object の equals()（== と同じ参照の比較）が使われ、中身が同じでも false。record の toString() は Point[x=0, y=2] の形式になる。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-009","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static String f(int... a) { return \"varargs\" + a.length; }\n    static String f(long a, long b) { return \"long2\"; }\n    static String f(Integer a) { return \"Integer\"; }\n    static String f(Object a) { return \"Object\"; }\n    static String f(double a) { return \"double\"; }\n\n    public static void main(String[] args) {\n        byte b = 1;\n        Integer boxed = 7;\n        System.out.print(f(b) + \" \");\n        System.out.print(f(3, 4) + \" \");\n        System.out.print(f(boxed) + \" \");\n        System.out.print(f() + \" \");\n        System.out.println(f('A'));\n    }\n}","choices":["double long2 Integer varargs0 double","Integer long2 Integer varargs0 Object","varargs1 varargs2 Integer varargs0 varargs1","double varargs2 Integer varargs0 double","double long2 Object varargs0 Object","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"オーバーロードは「①完全一致または拡大変換 → ②ボクシング・アンボクシング → ③可変長引数」の段階順に探され、前の段階で見つかればそこで決まる。f(b) と f('A') は byte・char から double への拡大変換で①の f(double) が見つかるので double（そもそも byte は Integer にはボクシングできない）。f(3, 4) も int→long の拡大変換で①の f(long, long) に決まり、可変長引数の int... は③なので選ばれない。f(boxed) は①で f(Integer) と f(Object) の両方が候補になり、より具体的な Integer が選ばれる。f() は引数0個を受け取れるのが可変長引数だけなので varargs0。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-010","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"enum Size {\n    S(1), M(2), L(3);\n    private final int level;\n    Size(int level) {\n        this.level = level;\n        System.out.print(\"[\" + name() + \"]\");\n    }\n    int level() { return level; }\n}\npublic class Main {\n    static String label(Size s) {\n        switch (s) {\n            case S: return \"small\";\n            case M:\n            case L: return \"big\" + s.level();\n            default: return \"?\";\n        }\n    }\n    public static void main(String[] args) {\n        System.out.print(\"start\");\n        Size x = Size.valueOf(\"M\");\n        System.out.println(\" \" + label(x) + \" \" + x.ordinal());\n        for (Size s : Size.values()) {\n            System.out.print(label(s) + \" \");\n        }\n    }\n}","choices":["start[S][M][L] big2 1\nsmall big2 big3","[S][M][L]start big2 1\nsmall big2 big3","start[M] big2 1\nsmall big2 big3","start[S][M][L] big2 2\nsmall big2 big3","13行目でコンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"enum の定数は、その enum が初めて使われたとき（ここでは Size.valueOf の呼び出し時）に、宣言順に1回ずつコンストラクタで作られる。そのため start の後に [S][M][L] が続き、values() を呼んでも作り直されることはない。ordinal() は0から数えた宣言順なので M は 1。switch の case には enum 定数を型名なしで書くのが正しく（Java 17 では case Size.S: と書く方がコンパイルエラー）、M には処理が無いので下の case L へフォールスルーして \"big\" + 2 を返す。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-011","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    public static void main(String[] args) {\n        int[] values = {4, 0, -2, 6};\n        for (int v : values) {\n            try {\n                System.out.print(Calc.half(v) + \" \");\n            } catch (ArithmeticException e) {\n                System.out.print(\"AE \");\n            } finally {\n                System.out.print(\"F \");\n            }\n        }\n        System.out.print(\"end\");\n    }\n\n    static class Calc {\n        static int half(int n) {\n            if (n == 0) throw new ArithmeticException(\"zero\");\n            if (n < 0) throw new IllegalArgumentException(\"neg\");\n            return n / 2;\n        }\n    }\n}","choices":["2 F AE F F と表示された後、IllegalArgumentException がスローされて終了する","2 F AE F と表示された後、IllegalArgumentException がスローされて終了する","2 F AE F AE F 3 F end と表示される","2 F AE F F 3 F end と表示される","19行目でコンパイルエラー"],"answer":[0],"explain":"half() は static メソッドなので、インスタンスを作らずに Calc.half(v) の形で呼べる（Calc は Main の中で宣言したネストクラスなので、Main の中からは Calc という名前だけで参照できる）。ArithmeticException と IllegalArgumentException はどちらも非検査例外（RuntimeException のサブクラス）なので、throws 宣言が無くてもコンパイルは通る。4 は 2 を表示して F、0 は ArithmeticException が catch されて AE と F。-2 で発生した IllegalArgumentException は ArithmeticException の catch では捕まらないが、finally の F が表示されてから main の外へ伝わり、プログラムは異常終了する（6 と end は表示されない）。","topic":"総合問題","sub":"総合"},{"id":"mix-012","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> a = new ArrayList<>(List.of(3, 1, 4, 1, 5, 9, 2, 6));\n        List<Integer> b = new ArrayList<>(a);\n        for (int i = 0; i < a.size(); i++) {\n            if (a.get(i) < 5) {\n                a.remove(i);\n            }\n        }\n        for (int i = b.size() - 1; i >= 0; i--) {\n            if (b.get(i) < 5) {\n                b.remove(i);\n            }\n        }\n        System.out.println(a + \" \" + b);\n    }\n}","choices":["[1, 1, 5, 9, 6] [5, 9, 6]","[5, 9, 6] [5, 9, 6]","[1, 1, 5, 9, 6] [1, 1, 5, 9, 6]","実行時に ConcurrentModificationException がスローされる","実行時に IndexOutOfBoundsException がスローされる","コンパイルエラー"],"answer":[0],"explain":"remove(i) で要素を消すと後ろの要素が1つずつ前に詰まるが、前から回すループでは i がそのまま i++ されるので、詰めて来た要素が検査されずに飛ばされる。a では、i=0 で 3 を消すと次の 1 が、i=1 で 4 を消すと次の 1 が前に詰まって来て飛ばされる。i=4 の 2 は検査されて消え（その後に詰まって来た 6 は飛ばされるが 5 以上なので影響なし）、[1, 1, 5, 9, 6] が残る。なお i は int なので、呼ばれるのは値ではなく位置で消す remove(int index) である。後ろから回すループでは、詰まって来るのは検査済みの要素だけなので飛ばしが起きず、b は 5 未満がすべて消えて [5, 9, 6] になる（new ArrayList<>(a) は別のリストを作るコピーなので、a の変更は b に影響しない）。どちらのループもイテレータを使わないので ConcurrentModificationException は起きず、i は毎回 size() 未満の範囲で使われるので範囲外にもならない。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-013","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    public static void main(String[] args) {\n        int count = 0;\n        for (int i = Integer.MAX_VALUE - 2; i > 0; i++) {\n            count++;\n        }\n        System.out.println(count);\n\n        byte b = 125;\n        for (int k = 0; k < 5; k++) {\n            b++;\n        }\n        System.out.println(b);\n\n        int v = 1;\n        int n = 0;\n        while (v > 0) {\n            v *= 2;\n            n++;\n        }\n        System.out.println(n + \" \" + v);\n    }\n}","choices":["3\n-126\n31 -2147483648","3\n-126\n32 0","2\n-126\n31 -2147483648","無限ループになる","11行目でコンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"int の最大値 2147483647 を超えると、例外にはならずに桁あふれ（オーバーフロー）して負の側へ回り込む（最大値 + 1 は最小値 -2147483648）。1つ目のループは i が MAX_VALUE-2、MAX_VALUE-1、MAX_VALUE の3回まわり、次の i++ で負になって終了するので 3。byte の b++ は暗黙のキャストを含むのでコンパイルでき、127 の次は -128 になるため 125→126→127→-128→-127→-126。v は2倍を繰り返して30回目の 2 の30乗（1073741824）までは正だが、31回目は 2 の31乗が int に収まらず -2147483648 になってループが終わるので、31 -2147483648。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-014","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static int count = 0;\n\n    static boolean check(String tag, boolean result) {\n        count++;\n        System.out.print(tag);\n        return result;\n    }\n\n    public static void main(String[] args) {\n        boolean r1 = check(\"A\", false) && check(\"B\", true) || check(\"C\", true);\n        System.out.println(\" \" + r1);\n        boolean r2 = check(\"D\", true) || check(\"E\", false) && check(\"F\", false);\n        System.out.println(\" \" + r2);\n        boolean r3 = check(\"G\", false) & check(\"H\", true) | check(\"I\", false);\n        System.out.println(\" \" + r3);\n        System.out.println(count);\n    }\n}","choices":["AC true\nD true\nGHI false\n6","AC true\nDF false\nGHI false\n7","ABC true\nDEF true\nGHI false\n9","AC true\nD true\nGI false\n5","A false\nD true\nG false\n3","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"&& は || より優先順位が高いので、r1 は (A && B) || C、r2 は D || (E && F) と解釈される。r1 は A が false なので B は評価されず、|| の右の C が評価されて true（表示は AC）。r2 は D が true の時点で || の右側 (E && F) 全体が評価されない（表示は D）。& と | は短絡評価をしないので、r3 は G・H・I がすべて評価されて (false & true) | false で false になり、check() の呼び出しは 2 + 1 + 3 = 6 回。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-015","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static void modify(String s, StringBuilder sb, int[] arr) {\n        s = s.toUpperCase();\n        sb.append(s);\n        sb = new StringBuilder(\"new\");\n        sb.append(\"!\");\n        arr[0] = s.length();\n        arr = new int[] {99};\n    }\n\n    public static void main(String[] args) {\n        String s = \"java\";\n        StringBuilder sb = new StringBuilder(\"hi-\");\n        int[] arr = {0};\n        modify(s, sb, arr);\n        System.out.println(s + \" \" + sb + \" \" + arr[0]);\n        String t = s.replace('a', 'o').substring(1, 3);\n        sb.insert(2, t).reverse();\n        System.out.println(t + \" \" + sb);\n    }\n}","choices":["java hi-JAVA 4\nov AVAJ-voih","JAVA hi-JAVA 4\nAV AVAJ-VAih","java new! 99\nov !wvoen","java hi- 0\nov -voih","java hi-JAVA 4\novo AVAJ-ovoih","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"Java の引数は値渡しで、参照型の場合は「参照のコピー」が渡される。modify() の中で s・sb・arr に新しいオブジェクトを代入しても、仮引数の参照が付け替わるだけで main の変数には影響しない。一方、付け替える前の sb.append(s) と arr[0] = s.length() は main と同じオブジェクトを変更するので、sb は hi-JAVA、arr[0] は \"JAVA\" の長さの 4 になる（String は不変なので main の s は java のまま）。t は \"jovo\" のインデックス1から、終了位置3の手前（インデックス2）までなので ov。sb はインデックス2の位置に ov を挿入して hiov-JAVA になり、reverse() で AVAJ-voih になる。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-016","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"interface Pet { String name(); }\nclass Animal { }\nclass Dog extends Animal implements Pet { public String name() { return \"dog\"; } }\nclass Cat extends Animal { }\npublic class Main {\n    public static void main(String[] args) {\n        Animal[] animals = { new Dog(), new Cat(), new Dog() };\n        for (Animal a : animals) {\n            if (a instanceof Pet p) {\n                System.out.print(p.name() + \" \");\n            }\n        }\n        for (Animal a : animals) {\n            Pet p = (Pet) a;\n            System.out.print(\"ok \");\n        }\n        System.out.println(\"end\");\n    }\n}","choices":["dog dog ok と表示された後、ClassCastException がスローされて終了する","dog dog ok ok ok end と表示される","dog dog と表示された後、ClassCastException がスローされて終了する","14行目でコンパイルエラー","9行目でコンパイルエラー"],"answer":[0],"explain":"Animal は final クラスではないので、Animal 型の変数の中身が「Animal のサブクラスで、Pet も実装しているもの」である可能性がある。そのため Animal 自体が Pet を実装していなくても、Animal → Pet のキャストや instanceof はコンパイルが通る。1つ目のループでは Pet を実装した Dog だけが条件を満たすので dog dog と表示される。2つ目のループでは最初の Dog はキャストに成功して ok を表示するが、次の Cat は Pet を実装していないので、実行時に ClassCastException がスローされて終了する。","topic":"総合問題","sub":"総合"},{"id":"mix-017","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    public static void main(String[] args) {\n        final int limit = 100;\n        byte b = limit;\n        final char c = 'A' + 2;\n        short s = c;\n        int $count = 0, _tmp = 1;\n        long big = 2147483648;\n        float f = 7;\n        var total = b + s + $count + _tmp;\n        System.out.println(total + f);\n        System.out.println(big + total);\n    }\n}","choices":["4行目でコンパイルエラー","5行目でコンパイルエラー","6行目でコンパイルエラー","7行目でコンパイルエラー","8行目でコンパイルエラー","コンパイルが成功し、175.0 と 2147483816 が表示される"],"answer":[4],"explain":"L の付いていない整数リテラルは int 型なので、int の最大値 2147483647 を超える 2147483648 は、long 変数に代入する場合でも8行目でコンパイルエラーになる（2147483648L と書く必要がある）。4行目の limit と5行目の 'A' + 2 は定数（定数で初期化された final 変数や、リテラルだけの式）なので、値が代入先の範囲に収まればキャストなしで代入できる。6行目も c が final の定数（値 67）なので short に代入できる（final が無ければ char → short はキャストが必要でエラー）。7行目のように識別子は $ や _ で始めてよく（_ 1文字だけは不可）、9行目の int → float は拡大変換なので問題ない。","topic":"総合問題","sub":"総合"},{"id":"mix-018","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"abstract class Shape {\n    protected String name;\n    Shape(String name) { this.name = name; }\n    abstract double area();\n    Object describe() { return name; }\n    static String unit() { return \"cm\"; }\n}\nclass Square extends Shape {\n    private final double side;\n    Square(double side) {\n        super(\"square\");\n        this.side = side;\n    }\n    public double area() { return side * side; }\n    @Override\n    String describe() { return name + \":\" + area(); }\n    static String unit() { return \"mm\"; }\n}\nclass Circle extends Shape {\n    double r;\n    Circle(double r) { this.r = r; }\n    double area() { return 3 * r * r; }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Shape s = new Square(2);\n        System.out.println(s.describe() + \" \" + s.unit());\n    }\n}","choices":["14行目でコンパイルエラー","16行目でコンパイルエラー","17行目でコンパイルエラー","21行目でコンパイルエラー","27行目でコンパイルエラー","コンパイルが成功し、square:4.0 cm と表示される"],"answer":[3],"explain":"Circle のコンストラクタには super(...) が書かれていないので、先頭に引数なしの super() が暗黙に補われる。しかし Shape には Shape(String) しか無く、引数なしのコンストラクタが存在しないため、21行目がコンパイルエラーになる。14行目はアクセス修飾子を広げる（無指定 → public）オーバーライドなので可、16行目は戻り値を Object のサブクラスの String にする共変戻り値なので可。17行目は static メソッド同士なので、オーバーライドではなく隠蔽として成立する。27行目のようにインスタンス経由で static メソッドを呼ぶ書き方も、推奨はされないがコンパイルは通る。","topic":"総合問題","sub":"総合"},{"id":"mix-019","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.io.IOException;\n\npublic class Main {\n    static int parse(String s) throws IOException {\n        if (s.isEmpty()) throw new IOException(\"empty\");\n        return Integer.parseInt(s);\n    }\n    static void validate(int n) {\n        if (n < 0) throw new IllegalStateException(\"negative\");\n    }\n    public static void main(String[] args) {\n        int sum = 0;\n        for (String s : new String[] {\"1\", \"\", \"x\"}) {\n            try {\n                int n = parse(s);\n                validate(n);\n                sum += n;\n            } catch (IOException | NumberFormatException e) {\n                sum += 10;\n            } catch (RuntimeException e) {\n                sum += 100;\n            }\n        }\n        System.out.println(sum + parse(\"5\"));\n    }\n}","choices":["9行目でコンパイルエラー","13行目でコンパイルエラー","18行目でコンパイルエラー","20行目でコンパイルエラー","24行目でコンパイルエラー","コンパイルが成功し、26 と表示される"],"answer":[4],"explain":"parse() は検査例外の IOException を throws 宣言しているので、呼び出し側は catch するか throws で宣言しなければならない。15行目の呼び出しは try-catch で捕まえているが、24行目の parse(\"5\") は try の外にあり、main にも throws が無いのでコンパイルエラーになる。9行目の IllegalStateException は非検査例外なので throws 宣言は要らない。18行目のマルチキャッチは IOException と NumberFormatException に継承関係が無いので可、20行目は狭い例外（NumberFormatException）を先に捕まえてから広い RuntimeException を捕まえる順序なので可。13行目のように拡張 for の右側に配列を直接 new で書くこともできる。","topic":"総合問題","sub":"総合"},{"id":"mix-020","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    public static void main(String[] args) {\n        String cmd = \"stop\";\n        int code = switch (cmd) {\n            case \"go\", \"run\" -> 1;\n            case \"stop\" -> {\n                int base = 10;\n                yield base * 2;\n            }\n            default -> -1;\n        };\n        check: {\n            if (code > 5) break check;\n            if (code < 0) continue check;\n            System.out.println(\"small\");\n        }\n        switch (code) {\n            default:\n                System.out.println(\"other\");\n            case 20:\n                System.out.println(\"twenty\");\n        }\n        String label = switch (code) {\n            case 1 -> \"one\";\n            case 20 -> \"twenty\";\n            default -> \"?\";\n        };\n        System.out.println(label);\n    }\n}","choices":["5行目でコンパイルエラー","8行目でコンパイルエラー","13行目でコンパイルエラー","14行目でコンパイルエラー","18行目でコンパイルエラー","コンパイルが成功し、twenty が2行表示される"],"answer":[3],"explain":"continue は「ループの次の周回へ進む」命令なので、ラベルを付ける場合もそのラベルはループ（for・while・do）に付いていなければならない。check はブロックに付いたラベルなので、14行目の continue check はコンパイルエラーになる。一方 break はラベル付きのブロックからも抜けられるので、13行目は可。5行目のように case にカンマで複数の値を並べるのも、8行目のように yield でブロックから switch 式の値を返すのも正しい書き方。18行目のように default を先頭に書くこともできる（default の位置に決まりは無く、switch 式でも同じ）。","topic":"総合問題","sub":"総合"},{"id":"mix-021","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"interface Priced {\n    int RATE = 10;\n    int price();\n    default int withTax() { return price() + price() * RATE / 100; }\n    private int half() { return price() / 2; }\n    static Priced of(int p) { return () -> p; }\n}\nrecord Item(String name, int price) implements Priced {\n    static int created = 0;\n    Item {\n        created++;\n    }\n    int discount = 0;\n    public String name() { return name.toUpperCase(); }\n}\nenum Plan implements Priced {\n    BASIC { public int price() { return 100; } },\n    PRO { public int price() { return 300; } }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Item item = new Item(\"pen\", 200);\n        System.out.println(item.name() + \" \" + item.withTax() + \" \" + Plan.PRO.withTax() + \" \" + Item.created);\n    }\n}","choices":["5行目でコンパイルエラー","9行目でコンパイルエラー","13行目でコンパイルエラー","14行目でコンパイルエラー","17行目でコンパイルエラー","コンパイルが成功し、PEN 220 330 1 と表示される"],"answer":[2],"explain":"record にはレコードコンポーネント（ヘッダーの String name, int price）以外のインスタンスフィールドを追加できないので、13行目がコンパイルエラーになる。9行目のような static フィールドは書けるし、それをコンパクトコンストラクタで増やすのも問題ない。5行目のように、インターフェースには Java 9 以降 private メソッドを書ける。14行目はアクセサ name() を public で明示的に定義し直しているので可（public でないとエラー）。17・18行目は enum の各定数が本体 { } の中で price() を実装しているので、enum 自体に price() が無くてもよい。","topic":"総合問題","sub":"総合"},{"id":"mix-022","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.ArrayList;\nimport java.util.List;\nimport java.util.function.Consumer;\nimport java.util.function.Function;\nimport java.util.function.Predicate;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> names = new ArrayList<>(List.of(\"Ann\", \"Bob\", \"Chris\"));\n        var copy = new ArrayList<>(names);\n        Consumer<String> touch = s -> s.length();\n        Function<String, Integer> len = s -> s.length();\n        Predicate<String> hasO = s -> s.indexOf(\"o\");\n        int total = 0;\n        for (String n : names) {\n            touch.accept(n);\n            total += len.apply(n);\n        }\n        names.removeIf(s -> s.length() > 3);\n        System.out.println(total + \" \" + names + \" \" + copy.size());\n    }\n}","choices":["10行目でコンパイルエラー","11行目でコンパイルエラー","13行目でコンパイルエラー","17行目でコンパイルエラー","19行目でコンパイルエラー","コンパイルが成功し、11 [Ann, Bob] 3 と表示される"],"answer":[2],"explain":"Predicate<T> の test() は boolean を返すので、ラムダ式の本体も boolean になる式でなければならない。s.indexOf(\"o\") は int を返すため、13行目がコンパイルエラーになる。11行目の Consumer<T> の accept() は戻り値が void だが、本体がメソッド呼び出しのように「文としても書ける式」なら戻り値は捨てられるので可。10行目の var は new ArrayList<>(names) から ArrayList<String> と推論され、17行目は len.apply(n) の Integer が自動でアンボクシングされて total に足される。19行目の removeIf() は Predicate のラムダを受け取り、条件に合う要素をまとめて削除する。","topic":"総合問題","sub":"総合"},{"id":"mix-023","type":"multi","q":"コンパイルが通るものを【すべて】選べ（クラス宣言の無いコード片は main メソッドの中に書いたものとする）。","choices":["enum E { A, B, C }\nclass T { int f(E e) { return switch (e) { case A -> 1; case B -> 2; }; } }","String k = \"x\";\nint v = switch (k) { case \"x\": yield 1; default: yield 0; };","int n = 1;\nswitch (n) { case 1 -> \"one\"; default -> \"other\"; }","int n = 3;\nint v = switch (n) { case 1, 2 -> 10; default -> { int w = n * 2; yield w; } };","enum E { A, B }\nclass T { int f(E e) { return switch (e) { case A -> 1; case B -> 2; }; } }","int n = 1;\nswitch (n) { case 1: yield 5; default: break; }"],"answer":[1,3,4],"explain":"値を返す switch 式は網羅的でなければならない。enum の全定数を case に書けば default が無くても網羅的とみなされるが（定数が A と B だけなら可）、定数 C が漏れている場合はエラーになる（int や String が対象なら default が必須）。switch 式でもコロン形式の case は使え、その場合は yield で値を返す（case \"x\": yield 1; は可）。アロー形式でブロックを書くときも、ブロックの中から yield で値を返せばよい。値を返さない switch 文では、アローの右側に \"one\" のような値だけを書くことはできず、yield も switch 式の中でしか使えないのでエラー。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-024","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ（各選択肢は、それぞれ1つのソースファイルにそのまま書いたものとする）。","choices":["class A { final int x; A() { this(5); } A(int v) { x = v; } }","class A { private A() { } }\nclass B extends A { }","record R(int v) { R { v = Math.abs(v); } }","record R(int v) { R(int v) { } }","class A { A() { this(1); } A(int n) { this(); } }","class A { static int count; final int id; A() { id = ++count; } }"],"answer":[1,3,4],"explain":"final フィールドはどのコンストラクタを経由しても必ず1回だけ代入される必要があり、this(5) で呼んだ A(int) の中で代入するものや、static な count を使って id = ++count と1回代入するものは可。record のコンパクトコンストラクタは引数 v を代入し直すだけでよく（フィールドへの代入は本体の後で自動で行われる）、可。一方、引数リストを書いた（コンパクトでない）標準コンストラクタ（カノニカルコンストラクタ。全コンポーネントを引数に取るもの）R(int v) { } では this.v = v; を自分で書かないと、フィールドが未初期化でエラー。this(...) で互いを呼び合うコンストラクタは、コンパイラが循環を検出してコンパイルエラーにする（メソッドの無限再帰はコンパイルが通り、実行時に StackOverflowError になるのとは違う）。A と B は別々のトップレベルクラスなので、B に自動で付くデフォルトコンストラクタが呼ぶ super() から、A の private な A() は呼べずエラー。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-025","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["interface I { default void m() { } }\nclass C implements I { void m() { } }","interface I { default void m() { } }\nabstract class A implements I { public abstract void m(); }","interface I { int X = 1; }\nclass C implements I { void f() { X = 2; } }","interface I { void m(); }\nabstract class A implements I { }","abstract class A { private abstract void m(); }","interface I { void m(); }\ninterface J { void m(); }\nclass C implements I, J { public void m() { } }"],"answer":[0,2,4],"explain":"インターフェースのメソッドは、private を付けたもの以外はアクセス修飾子を省略しても暗黙に public なので、default メソッドをオーバーライドする側も public が必要で、void m() と無指定で書く（アクセスを狭める）とエラー。インターフェースのフィールドは暗黙に public static final の定数なので、X = 2 と代入するとエラー。抽象クラスはインターフェースの抽象メソッドを実装しないままでよく、default メソッドを public abstract で宣言し直してサブクラスに実装を強制することもできる。private なメソッドはオーバーライドできないので abstract と組み合わせるとエラー。I と J に同じシグネチャの抽象メソッド m() があっても衝突にはならず、public void m() を1つ実装すれば両方を満たせる。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-026","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["class A { static void m(byte b) { } static void t() { m(10); } }","class A { static void m(long a) { } static void m(Integer a) { } static void t() { m(1); } }","class A { static void m(Integer a, int b) { } static void m(int a, Integer b) { } static void t() { m(1, 2); } }","class A { static void m(int... a) { } static void m(int[] a) { } }","class A { static void m(double d) { } static void t() { m(5L); } }","class A { static void m(Number n) { } static void t() { m(1); m(2.5); } }"],"answer":[0,2,3],"explain":"メソッド呼び出しの引数には、代入のときの「定数なら範囲内で縮小してよい」という特例が無いので、int の 10 を byte の仮引数に渡すとエラーになる（byte b = 10; なら可）。オーバーロードは①完全一致・拡大変換 → ②ボクシング・アンボクシング → ③可変長引数の順に探されるので、m(1) は①で long 版に決まり、Integer 版とあいまいにはならない。m(Integer, int) と m(int, Integer) に m(1, 2) を渡すと、どちらも②で1回ずつボクシングが必要になって優劣が付かず、あいまいな呼び出しとしてエラーになる。可変長引数 int... の実体は int[] なので、m(int...) と m(int[]) は同じシグネチャとなり同時には定義できない。long の 5L は double へ拡大でき、Number の仮引数には 1 と 2.5 がボクシング後の Integer・Double として渡せる。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"mix-027","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ（コード片は main メソッドの中に書いたものとする）。","choices":["int[] counter = {0};\nRunnable r = () -> counter[0]++;","for (int i = 0; i < 3; i++) {\n    Runnable r = () -> System.out.println(i);\n}","for (String s : new String[] {\"a\", \"b\"}) {\n    Runnable r = () -> System.out.println(s);\n}","var f = (String s) -> s.length();","var list = new java.util.ArrayList<>();\nlist.add(\"a\");\nlist.add(1);","var x = 10;\nx = \"ten\";"],"answer":[1,3,5],"explain":"ラムダ式から参照するローカル変数は実質的に final（初期化後に再代入しない）でなければならない。通常の for 文の i は i++ で書き換えられるのでラムダから参照できずエラーだが、拡張 for 文の s は周回ごとに新しく作られて再代入されないので参照できる。配列 counter の参照自体は変えずに中身の counter[0] を変えるだけなら可。var は初期化式から型を1回だけ決めるので、int に決まった x に \"ten\" を代入するとエラーになり、ラムダ式だけでは関数型インターフェースが決まらないので var f = (String s) -> ... もエラー。new java.util.ArrayList<>() を var で受けると ArrayList<Object> と推論されるので、String も Integer も追加できる。","topic":"総合問題","mono":1,"sub":"総合"},{"id":"exg-001","type":"multi","q":"オーバーライドとして、コンパイルが通るものを【すべて】選べ（java.io は完全修飾名で書いている）。","choices":["class P { void m() throws java.io.IOException {} }\nclass C extends P { void m() {} }","class P { void m() throws java.io.IOException {} }\nclass C extends P { void m() throws Exception {} }","class P { void m() throws java.io.IOException {} }\nclass C extends P { void m() throws java.io.FileNotFoundException {} }","class P { void m() {} }\nclass C extends P { void m() throws java.io.IOException {} }","class P { void m() {} }\nclass C extends P { void m() throws IllegalStateException {} }"],"answer":[0,2,4],"explain":"オーバーライドしたメソッドの throws に書ける検査例外は、元のメソッドが宣言している例外と同じか、そのサブクラスだけ（FileNotFoundException は IOException のサブクラスなので OK。減らす・書かないのも自由）。IOException を Exception に広げたり、throws の無いメソッドに IOException を追加したりするとコンパイルエラー。IllegalStateException のような非検査例外は、元のメソッドの throws に関係なく書ける。","topic":"例外処理","mono":1},{"id":"exg-002","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Base {\n    Base() throws Exception {\n        System.out.println(\"Base\");\n    }\n}\nclass Sub extends Base {\n}\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        new Sub();\n    }\n}","choices":["Base と表示される","2行目でコンパイルエラー","6行目でコンパイルエラー","10行目でコンパイルエラー"],"answer":[2],"explain":"コンストラクタが検査例外を throws していると、それを呼び出す側で catch するか throws を宣言しなければならない。Sub にはコンストラクタが書かれていないので、コンパイラが Sub() { super(); } というデフォルトコンストラクタを補うが、これには throws が付かないため、super() の Exception を処理できず6行目でエラーになる。Sub() throws Exception { } と明示的に書けば通り、Base と表示される（super() は先頭に書く決まりなので、try で囲んで処理することはできない）。","topic":"例外処理"},{"id":"exg-003","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Conn {\n    public void close() {\n        System.out.println(\"close\");\n    }\n}\npublic class Main {\n    public static void main(String[] args) {\n        try (Conn c = new Conn()) {\n            System.out.println(\"use\");\n        } finally {\n            System.out.println(\"end\");\n        }\n    }\n}","choices":["use → close → end の順に表示される","use → end の順に表示される","8行目でコンパイルエラー","10行目でコンパイルエラー"],"answer":[2],"explain":"try-with-resources の ( ) に書けるのは、AutoCloseable を実装した型（Closeable など、AutoCloseable を継承したインターフェースの型も含む）だけ。Conn は close() メソッドを持っているが implements AutoCloseable が無いので、8行目でコンパイルエラーになる。class Conn implements AutoCloseable と書けば、use → close → end の順に表示される（close は finally より先に実行される）。","topic":"例外処理"},{"id":"exg-004","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Res implements AutoCloseable {\n    public void close() {\n        System.out.println(\"close\");\n    }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Res r = new Res();\n        try (r) {\n            System.out.println(\"body\");\n        }\n        r = new Res();\n    }\n}","choices":["body → close の順に表示される","body だけが表示される","9行目でコンパイルエラー","12行目でコンパイルエラー"],"answer":[2],"explain":"Java 9 以降は、try の外で宣言した変数を try (r) のように書いてリソースにできる。ただし、その変数は final か実質的に final（宣言後に一度も再代入されない）でなければならない。12行目で再代入しているため r は実質的 final でなくなり、リソースとして使っている9行目がコンパイルエラーになる（再代入の行ではない）。","topic":"例外処理"},{"id":"exg-005","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Door implements AutoCloseable {\n    boolean open = true;\n    public void close() {\n        open = false;\n        System.out.print(\"close \");\n    }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Door d = new Door();\n        try (d) {\n            System.out.print(\"in \");\n        }\n        System.out.print(d.open);\n    }\n}","choices":["in close false","in false","in close true","14行目でコンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"try の外で宣言した変数を try (d) のようにリソースにした場合も、try ブロックを抜けるときに close() が自動で呼ばれる。変数 d は try の外で宣言しているので、try の後でも使える（中身は close 済みの状態）。try (Door d = new Door()) のように ( ) の中で宣言した変数なら、スコープは try ブロックの中だけになる。","topic":"例外処理","mono":1},{"id":"exg-006","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"class Res implements AutoCloseable {\n    public void close() {\n        throw new IllegalStateException(\"close\");\n    }\n}\npublic class Main {\n    static void run(boolean fail) {\n        try (Res r = new Res()) {\n            if (fail) throw new RuntimeException(\"body\");\n        } catch (RuntimeException e) {\n            System.out.print(e.getMessage() + \":\" + e.getSuppressed().length + \" \");\n        }\n    }\n    public static void main(String[] args) {\n        run(true);\n        run(false);\n    }\n}","choices":["body:1 close:0","close:1 close:0","body:0 close:0","body:1 close:1","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"try ブロックで例外が発生し、続く close() でも例外が発生した場合、呼び出し側に届くのは try ブロックの例外で、close() の例外はそれに「抑制された例外」として追加され、getSuppressed() で取り出せる。try ブロックが正常に終わった場合は close() の例外がそのままスローされるので、抑制された例外は0個になる。","topic":"例外処理","mono":1},{"id":"exg-007","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"String e = \"start\";\ntry {\n    System.out.println(e.charAt(10));\n} catch (StringIndexOutOfBoundsException e) {\n    System.out.println(\"NG\");\n}","choices":["NG と表示される","3行目でコンパイルエラー","4行目でコンパイルエラー","実行時に StringIndexOutOfBoundsException がスローされる"],"answer":[2],"explain":"catch のパラメータも一種のローカル変数なので、スコープが重なる位置に同じ名前の変数があると宣言できない。1行目の変数 e のスコープはメソッドの終わりまで続くので、4行目の catch (… e) は二重定義となりコンパイルエラー（variable e is already defined）。catch のパラメータのスコープはその catch ブロックの中だけなので、ブロックの外では使えないが、catch を複数並べてどれも e と名付けるのは問題ない。","topic":"例外処理"},{"id":"exg-008","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static void work() {\n        try {\n            throw new IllegalArgumentException(\"try\");\n        } finally {\n            throw new IllegalStateException(\"finally\");\n        }\n    }\n    public static void main(String[] args) {\n        try {\n            work();\n        } catch (RuntimeException e) {\n            System.out.println(e.getMessage() + \" \" + e.getSuppressed().length);\n        }\n    }\n}","choices":["try 0","finally 0","finally 1","try 1","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[1],"explain":"finally ブロックで例外がスローされると、try ブロックで発生していた例外は捨てられ、finally の例外だけが呼び出し側に伝わる。try-with-resources の close() の例外と違い、元の例外は抑制された例外としても残らないので getSuppressed() は0個。元の例外の情報が失われるため、finally の中で例外を投げる書き方は避けるべき。","topic":"例外処理","mono":1},{"id":"exg-009","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static void test(int n) {\n        try {\n            try {\n                if (n == 0) throw new IllegalStateException();\n                System.out.print(\"a\");\n            } catch (IllegalStateException e) {\n                System.out.print(\"b\");\n                throw e;\n            } finally {\n                System.out.print(\"c\");\n            }\n            System.out.print(\"d\");\n        } catch (RuntimeException e) {\n            System.out.print(\"e\");\n        }\n    }\n    public static void main(String[] args) {\n        test(0);\n        System.out.print(\"|\");\n        test(1);\n    }\n}","choices":["bce|acd","bec|acd","bcde|acd","bce|ad","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"内側の catch で throw e; と再スローした例外は、外側の try の catch に渡される。ただし、内側の try 文を抜ける前に内側の finally が必ず実行されるので b → c → e の順になり、内側の try 文の後ろにある d は実行されない。例外が起きない test(1) でも finally は実行されるので a → c → d となる。","topic":"例外処理","mono":1},{"id":"exg-010","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ。","choices":["try { } catch (Exception e) { }","try { } catch (InterruptedException e) { }","try { } catch (ArithmeticException e) { }","try { } catch (IllegalArgumentException e) { } catch (NumberFormatException e) { }","try { } catch (Exception e) { } catch (Error e) { }"],"answer":[1,3],"explain":"try の中で何もスローしていなくても、Exception や、RuntimeException のサブクラス（ArithmeticException など）の catch は書ける。一方、InterruptedException のような検査例外は、try の中でスローされる可能性が無いと catch できずコンパイルエラー。NumberFormatException は IllegalArgumentException のサブクラスなので、後ろに書くと到達不能でエラー。Error は Exception のサブクラスではない（どちらも Throwable の直接のサブクラス）ので、catch (Exception e) の後ろに書いても到達できる。","topic":"例外処理","mono":1},{"id":"exg-011","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static void a() {\n        try {\n            b();\n            System.out.print(\"A1 \");\n        } finally {\n            System.out.print(\"A2 \");\n        }\n    }\n    static void b() {\n        try {\n            c();\n        } finally {\n            System.out.print(\"B \");\n        }\n    }\n    static void c() {\n        System.out.print(\"C \");\n        throw new IllegalStateException();\n    }\n    public static void main(String[] args) {\n        try {\n            a();\n        } catch (IllegalStateException e) {\n            System.out.print(\"main\");\n        }\n    }\n}","choices":["C B A2 main","C main B A2","C B A1 A2 main","C A2 B main","コンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"c() でスローされた例外は、catch が見つかるまで呼び出し元へ c → b → a → main とさかのぼって伝わる。b() と a() には catch が無いが、メソッドを抜ける前にそれぞれの finally は実行されるので、内側から B → A2 の順に表示される。b() の呼び出しが例外で中断されるので A1 は表示されず、最後に main の catch が実行される。","topic":"例外処理","mono":1},{"id":"exg-012","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    public static void main(String[] args) {\n        try {\n            throw null;\n        } catch (IllegalStateException e) {\n            System.out.println(\"ISE\");\n        } finally {\n            System.out.println(\"finally\");\n        }\n    }\n}","choices":["finally と表示された後、NullPointerException で異常終了する","何も表示されずに NullPointerException で異常終了する","4行目でコンパイルエラー","finally とだけ表示され、正常に終了する"],"answer":[0],"explain":"throw の対象が null だと、その場で NullPointerException がスローされる（throw null; は型の上では問題ないのでコンパイルは通る）。NullPointerException は IllegalStateException のサブクラスではないので catch されず、finally を実行した後に main の外まで伝わってプログラムが異常終了する。","topic":"例外処理"},{"id":"exg-013","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    public static void main(String[] args) {\n        try {\n            throw new StackOverflowError();\n        } catch (Exception e) {\n            System.out.println(\"Exception\");\n        } finally {\n            System.out.println(\"finally\");\n        }\n    }\n}","choices":["Exception → finally の順に表示される","finally と表示された後、StackOverflowError で異常終了する","4行目でコンパイルエラー","何も表示されずに StackOverflowError で異常終了する"],"answer":[1],"explain":"StackOverflowError（再帰呼び出しが深くなりすぎたときに JVM がスローするもの）は Error のサブクラスで、Exception のサブクラスではない。そのため catch (Exception e) では捕まえられず、finally を実行した後にプログラムが異常終了する。Error は非検査例外なので throws を宣言しなくてもスローでき、コンパイルは通る。","topic":"例外処理"},{"id":"exg-014","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static <T extends Number> double twice(T value) {\n        return value.doubleValue() * 2;\n    }\n    public static void main(String[] args) {\n        System.out.println(twice(3));\n        System.out.println(twice(\"4\"));\n    }\n}","choices":["6.0 と 8.0 が表示される","6.0 と表示された後、ClassCastException がスローされる","3行目でコンパイルエラー","7行目でコンパイルエラー"],"answer":[3],"explain":"<T extends Number> は「T は Number かそのサブクラスに限る」という境界の指定。境界があるので、T 型の引数に対して Number のメソッド（doubleValue() など）を呼べる。twice(3) は T が Integer になって通るが、String は Number のサブクラスではないので7行目でコンパイルエラーになる。","topic":"ラムダとAPI","sub":"ジェネリクス"},{"id":"exg-015","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> ints = new ArrayList<>(List.of(1, 2));\n        List<? extends Number> nums = ints;\n        Number first = nums.get(0);\n        nums.add(3);\n        System.out.println(first + \" \" + nums.size());\n    }\n}","choices":["1 3 と表示される","1 2 と表示される","8行目でコンパイルエラー","9行目でコンパイルエラー"],"answer":[3],"explain":"List<? extends Number> 型の変数には、List<Integer> や List<Double> など「Number かそのサブクラスのリスト」を代入できる。取り出した要素は必ず Number として扱えるので get は通る。しかし実体が List<Double> かもしれないため、Integer を含めて add はできず（null だけは可）、9行目でコンパイルエラーになる。","topic":"ラムダとAPI","sub":"ジェネリクス"},{"id":"exg-016","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static void fill(List<? super Integer> list) {\n        list.add(10);\n        list.add(20);\n    }\n    public static void main(String[] args) {\n        List<Number> nums = new ArrayList<>();\n        nums.add(1.5);\n        fill(nums);\n        List<Object> objs = new ArrayList<>();\n        fill(objs);\n        System.out.println(nums + \" \" + objs.size());\n    }\n}","choices":["[1.5, 10, 20] 2","[1.5, 10.0, 20.0] 2","[10, 20] 2","14行目でコンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"List<? super Integer> 型の引数には、List<Integer>・List<Number>・List<Object> のように「Integer かその上位の型（スーパークラスや、Comparable<Integer> などの実装しているインターフェース）のリスト」を渡せる。どのリストであっても Integer は格納できるので add(10) は通り、Integer のまま入るので 10.0 にはならない。逆に取り出すときは中身の型が決まらないので、Object 型としてしか受け取れない。","topic":"ラムダとAPI","mono":1,"sub":"ジェネリクス"},{"id":"exg-017","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.List;\n\npublic class Main {\n    static <T> T first(List<T> list) {\n        return list.get(0);\n    }\n    public static void main(String[] args) {\n        String s = first(List.of(\"x\", \"y\"));\n        Integer n = Main.<Integer>first(List.of(7, 8));\n        System.out.println(s.toUpperCase() + n * 2);\n    }\n}","choices":["X14","x14","8行目でコンパイルエラー","9行目でコンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"ジェネリックメソッドは、戻り値の型の前に <T> を書いて型パラメータを宣言する。T は引数から推論されるので、first(List.of(\"x\", \"y\")) の戻り値は String になり、キャスト無しで受け取れる。Main.<Integer>first(...) のように型引数を明示してもよい。n * 2 が先に計算されるので \"X\" + 14 で X14 となる。","topic":"ラムダとAPI","mono":1,"sub":"ジェネリクス"},{"id":"exg-018","type":"multi","q":"コンパイルエラーになるものを【すべて】選べ（java.util は完全修飾名で書いている）。","choices":["java.util.Map<String, java.util.List<Integer>> m = new java.util.HashMap<>();","java.util.List<> a = new java.util.ArrayList<String>();","var a = new java.util.ArrayList<>();\na.add(\"x\");\na.add(1);","var a = new java.util.ArrayList<>();\na.add(\"x\");\nString s = a.get(0);","java.util.Map<String, int> m = new java.util.HashMap<>();"],"answer":[1,3,4],"explain":"ダイヤモンド演算子 <> は new する側で型引数を省略する書き方で、変数の型の側には書けない。var と組み合わせて new java.util.ArrayList<>() と引数も無しで書くと、推論の手がかりが無いので ArrayList<Object> になり、何でも add できる代わりに get の戻り値は Object 型になる（String 型の変数には代入できない）。型引数に int などの基本データ型は使えないので、Map<String, Integer> と書く。","topic":"ラムダとAPI","mono":1,"sub":"ジェネリクス"},{"id":"exg-019","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> names = new ArrayList<>();\n        List raw = names;\n        raw.add(100);\n        System.out.println(\"size=\" + names.size());\n        String s = names.get(0);\n        System.out.println(s);\n    }\n}","choices":["size=1 と表示された後、ClassCastException がスローされる","何も表示されずに ClassCastException がスローされる","size=1 と 100 が表示される","8行目でコンパイルエラー"],"answer":[0],"explain":"型引数を付けない List（raw 型）を経由すると要素の型がチェックされず、String 用のリストに Integer を add できてしまう（unchecked の注意が出るだけで、コンパイルは通る）。実行時のリストは型引数の情報を持たない（型消去）ので、add の時点では例外にならない。names.get(0) の結果を String として受け取る10行目で、初めて ClassCastException が発生する。","topic":"ラムダとAPI","sub":"ジェネリクス"},{"id":"exg-020","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"public class Main {\n    static <T extends Comparable<T>> T max(T a, T b) {\n        return a.compareTo(b) >= 0 ? a : b;\n    }\n    public static void main(String[] args) {\n        System.out.println(max(\"apple\", \"banana\") + \" \" + max(3, 7));\n    }\n}","choices":["banana 7","apple 7","banana 3","2行目でコンパイルエラー","実行時に例外がスローされて異常終了する"],"answer":[0],"explain":"型パラメータの境界には、クラスでもインターフェースでも extends を使う（implements とは書かない）。<T extends Comparable<T>> と宣言すると、T 型の値に対して compareTo を呼べる。String の compareTo は辞書順なので \"banana\" の方が大きく、Integer は数値の大小なので 7 が返る。","topic":"ラムダとAPI","mono":1,"sub":"ジェネリクス"},{"id":"exg-021","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.*;\nimport java.awt.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> list = new ArrayList<>();\n        list.add(\"a\");\n        System.out.println(list);\n    }\n}","choices":["[a] と表示される","2行目でコンパイルエラー","6行目でコンパイルエラー","実行時に例外がスローされる"],"answer":[2],"explain":"java.util と java.awt には、どちらにも List という名前の型がある。* を使ったインポート同士で名前がぶつかっても import 文そのものはエラーにならないが、List を使った6行目で「どちらの List か決められない（reference to List is ambiguous）」としてコンパイルエラーになる。ArrayList は java.util にしか無いので問題ない。","topic":"パッケージとモジュール","sub":"パッケージ"},{"id":"exg-022","type":"multi","q":"コンパイルが通るものを【すべて】選べ。","choices":["import java.util.*;\nimport java.awt.*;\nimport java.util.List;\nclass A { List<String> x; }","import java.util.List;\nimport java.awt.List;\nclass A { }","import java.util.*;\nimport java.awt.*;\nclass A { ArrayList<String> x; }","class A { java.util.List<String> x; java.awt.List y; }","import java.util;\nclass A { List<String> x; }"],"answer":[0,2,3],"explain":"単一型インポート（import java.util.List;）は * のインポートより優先されるので、java.awt.* と併用しても List は java.util.List に決まる。同じ単純名の型を単一型インポートで2つ取り込むと、使っていなくても import の時点でコンパイルエラー。完全修飾名で書けば、import 無しで同名のクラスを使い分けられる。import java.util; のようにパッケージ名だけを書くことはできない（* か型名まで書く）。","topic":"パッケージとモジュール","mono":1,"sub":"パッケージ"},{"id":"exg-023","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"package app;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(java.util.List.of(\"a\"));\n    }\n}\nimport java.util.ArrayList;","choices":["[a] と表示される","1行目でコンパイルエラー","5行目でコンパイルエラー","8行目でコンパイルエラー"],"answer":[3],"explain":"ソースファイルには、package 宣言 → import 文 → クラスなどの型宣言、の順に書く決まりがある。import 文は型宣言より前にしか書けないので、クラスの後ろに置いた8行目の import がコンパイルエラーになる（class, interface, enum, or record expected）。5行目は java.util.List と完全修飾名で書いているので import が無くても問題なく、1行目の package 宣言も先頭にあるので正しい。","topic":"パッケージとモジュール","sub":"パッケージ"},{"id":"exg-024","type":"single","q":"次のコードをコンパイル・実行するとどうなる？","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> list = new ArrayList<>(List.of(3, 1, 2));\n        Function<Integer, Integer> f = x -> x * 10;\n        System.out.println(f.apply(list.get(0)));\n    }\n}","choices":["30 と表示される","5行目でコンパイルエラー","6行目でコンパイルエラー","実行時に例外がスローされる"],"answer":[2],"explain":"import java.util.*; で使えるようになるのは java.util パッケージ直下の型だけで、java.util.function のようなサブパッケージの型は含まれない（名前が階層的に見えても、パッケージとしては別物）。Function は java.util.function パッケージにあるので import java.util.function.Function; などを別に書く必要があり、6行目でコンパイルエラーになる。","topic":"パッケージとモジュール","sub":"パッケージ"},{"id":"exg-025","type":"single","q":"モジュール app の module-info.java には requires lib; が、モジュール lib の module-info.java には requires transitive util; が書かれている。util は com.example.util パッケージを exports している。正しい説明はどれか。","choices":["app は requires util; を書かなくても com.example.util パッケージを使える","app が com.example.util パッケージを使うには、requires util; も書く必要がある","requires transitive により、util が exports していないパッケージも app から使えるようになる","requires transitive と書いた lib 自身は util を使えず、lib を requires したモジュールだけが使える"],"answer":[0],"explain":"requires transitive は、自分（lib）を requires したモジュールにも、その依存先（util）を読めるようにする指定。そのため app は requires lib; だけで util を読める。ただし使えるのは util が exports しているパッケージだけで、lib 自身も通常の requires と同じように util を使える。","topic":"パッケージとモジュール","sub":"モジュール"},{"id":"exg-026","type":"single","q":"モジュール com.shop に含まれるクラス com.shop.app.Main を実行したい。モジュールは mods ディレクトリに置いてある。正しいコマンドはどれか。","choices":["java -p mods -m com.shop/com.shop.app.Main","java -m mods -p com.shop/com.shop.app.Main","java -p mods -m com.shop.app.Main/com.shop","java -cp mods -m com.shop.app.Main"],"answer":[0],"explain":"-p（--module-path）でモジュールを探す場所を、-m（--module）で「モジュール名/メインクラスの完全修飾名」を指定する。-cp（--class-path）はクラスパスの指定で、モジュールパスとは別物。モジュールの JAR にメインクラスが記録されていれば、java -p mods -m com.shop のようにクラス名を省略することもできる。","topic":"パッケージとモジュール","sub":"モジュール"}];
